-- =============================================================================
-- Seereon HRMS — database, PostgreSQL 16
-- Version 1.0 · generated from the Seereon HRMS v5.1 product model · Seereon
-- 339 tables · 5386 columns · 1417 foreign keys
--
-- Conventions
--   * id uuid PRIMARY KEY on every table; business identifiers live in <entity>_code
--   * tenant tables carry org_id and are protected by row-level security
--   * created_at / created_by / updated_at / updated_by / row_version on every table;
--     deleted_at / deleted_by on tables the product archives instead of deleting
--   * money numeric(14,2), percentages numeric(5,2), dates date, instants timestamptz
--   * enumerations and formats enforced by CHECK constraints
--
-- Load order: this file is self-contained -- psql -d seerhr -f schema.sql
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS pg_trgm;


-- =============================================================================
-- Platform & Tenancy
-- =============================================================================

-- BiometricDevice — Registered attendance devices per organisation.
CREATE TABLE biometric_devices (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  biometric_device_code varchar(30) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  branch varchar(120) NOT NULL,
  device_model varchar(80) NOT NULL,
  serial_number varchar(80) NOT NULL,
  status varchar(20) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_biometric_devices_code UNIQUE (org_id, biometric_device_code),
  CONSTRAINT ck_biometric_devices_status CHECK (status IN ('Registered', 'Pending OEM Setup', 'Offline'))
);
-- CompanyGroup — A client's group of companies (holding level). Created by Seereon at onboarding ('Group of companies') or automatically when a single-company client adds its fi
CREATE TABLE company_groups (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_group_code varchar(20) NOT NULL,
  name varchar(200) NOT NULL,
  code varchar(30) NOT NULL,
  holding_entity varchar(200),
  country varchar(80) NOT NULL,
  created_on date NOT NULL,
  notes text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_company_groups_code UNIQUE (company_group_code)
);
-- GroupEmployment — Derived view: a person's employment records across the group's entities; group joining date drives gratuity.
CREATE TABLE group_employment_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  org_id uuid NOT NULL,
  joining_date date NOT NULL,
  end_date date,
  designation varchar(120) NOT NULL,
  is_current boolean NOT NULL,
  group_joining_date date NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_group_employment_records_key UNIQUE (employee_id, org_id, joining_date)
);
-- GroupTransferAssetDispositions — Child of group_transfer_requests — group_transfer_asset_dispositions (from assetDispositions[]: asset_id → assets.id, asset_name, disposition enum return|transf
CREATE TABLE group_transfer_asset_dispositions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  group_transfer_request_id uuid NOT NULL,
  asset_id uuid,
  asset_name varchar(120),
  disposition varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GroupTransferRequest — Inter-company employee transfer within a client group, confirmed by Seereon.
CREATE TABLE group_transfer_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  group_transfer_request_code varchar(20) NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  from_org_id uuid NOT NULL,
  to_org_id uuid NOT NULL,
  effective_date date NOT NULL,
  new_designation varchar(120) NOT NULL,
  reason text NOT NULL,
  status varchar(32) NOT NULL,
  raised_on date NOT NULL,
  user_id uuid NOT NULL,
  decided_on date,
  decided_by varchar(120),
  decision_note text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_group_transfer_requests_code UNIQUE (org_id, group_transfer_request_code),
  CONSTRAINT ck_group_transfer_requests_status CHECK (status IN ('Pending Seereon Confirmation', 'Confirmed', 'Rejected'))
);
-- Integration — Integration catalogue (reference data).
CREATE TABLE integrations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key varchar(30) NOT NULL,
  name varchar(80) NOT NULL,
  category varchar(20) NOT NULL,
  description text NOT NULL,
  is_popular boolean,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_integrations_code UNIQUE (key),
  CONSTRAINT ck_integrations_category CHECK (category IN ('Communication', 'Payments', 'Identity', 'Productivity', 'AI', 'Payroll', 'Storage', 'HRIS'))
);
-- Module — Product catalogue module (reference data).
CREATE TABLE modules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key varchar(30) NOT NULL,
  name varchar(80) NOT NULL,
  description text NOT NULL,
  submodules text[] NOT NULL,
  default_permissions text[] NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_modules_code UNIQUE (key)
);
-- AdConfig — Per-organisation Active Directory sync settings.
CREATE TABLE org_ad_configs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  enabled boolean NOT NULL,
  domain_controller varchar(255),
  sync_scope varchar(14),
  last_synced_at timestamptz,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_org_ad_configs_key UNIQUE (org_id),
  CONSTRAINT ck_org_ad_configs_sync_scope CHECK (sync_scope IN ('All users', 'Selected OUs'))
);
-- OrgAdFieldMappings — Child of org_ad_configs — org_ad_field_mappings (from fieldMapping[]: ad_attribute, seerhr_field)
CREATE TABLE org_ad_field_mappings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_ad_config_id uuid NOT NULL,
  ad_attribute varchar(120),
  seerhr_field varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- EmailTicketConfig — Email-to-ticket inbox settings per organisation.
CREATE TABLE org_email_ticket_configs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  enabled boolean NOT NULL,
  inbox_address varchar(254),
  routing_keyword varchar(60),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_org_email_ticket_configs_key UNIQUE (org_id)
);
-- SsoConfig — Per-organisation SSO settings.
CREATE TABLE org_sso_configs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  enabled boolean NOT NULL,
  provider varchar(4),
  idp_metadata_url text,
  email_domain varchar(120),
  auto_login_for_domain boolean NOT NULL,
  last_tested_at timestamptz,
  last_test_result varchar(14),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_org_sso_configs_key UNIQUE (org_id),
  CONSTRAINT ck_org_sso_configs_provider CHECK (provider IN ('SAML', 'OIDC')),
  CONSTRAINT ck_org_sso_configs_last_test_result CHECK (last_test_result IN ('Not connected', 'Success', 'Failed'))
);
-- OrgTicket — Legacy employee → org support tickets (seed only; superseded by the Helpdesk portal, not referenced).
CREATE TABLE org_support_tickets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_support_ticket_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  issue_type varchar(30) NOT NULL,
  severity varchar(10) NOT NULL,
  status varchar(12) NOT NULL,
  raised_on date NOT NULL,
  expected_on date NOT NULL,
  source varchar(10),
  email_thread jsonb,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_org_support_tickets_code UNIQUE (org_id, org_support_ticket_code),
  CONSTRAINT ck_org_support_tickets_issue_type CHECK (issue_type IN ('IT / Hardware', 'Software Access', 'SAP Logon', 'Email', 'HR Query', 'Payroll', 'Facilities', 'Other')),
  CONSTRAINT ck_org_support_tickets_severity CHECK (severity IN ('Low', 'Medium', 'High', 'Critical')),
  CONSTRAINT ck_org_support_tickets_status CHECK (status IN ('Unattended', 'Attended', 'Resolved')),
  CONSTRAINT ck_org_support_tickets_source CHECK (source IN ('Portal', 'Email'))
);
-- OrganizationAddresses — Child of organizations — organization_addresses (wizard step 2 — currently not persisted)
CREATE TABLE organization_addresses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- OrganizationBranch — Branch / location of an entity; employees and branch masters hang off it.
CREATE TABLE organization_branches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_branch_code varchar(40) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  city varchar(80),
  state varchar(80),
  address text,
  head_name varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_organization_branches_code UNIQUE (org_id, organization_branch_code)
);
-- OrganizationIntegration — Integration an organisation is allowed to activate.
CREATE TABLE organization_integrations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  integration_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_organization_integrations_key UNIQUE (org_id, integration_id)
);
-- OrganizationModule — Module enabled for an organisation by Seereon.
CREATE TABLE organization_modules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  module_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_organization_modules_key UNIQUE (org_id, module_id)
);
-- Organization — A legal entity / tenant company (GroupOrg). Holds the modules and integrations Seereon provisioned, subscription plan and onboarding metadata.
CREATE TABLE organizations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_code varchar(20) NOT NULL,
  code varchar(30) NOT NULL,
  name varchar(200) NOT NULL,
  legal_name varchar(200) NOT NULL,
  group_id uuid,
  industry varchar(80) NOT NULL,
  country varchar(80) NOT NULL,
  employee_count integer NOT NULL,
  status varchar(12) NOT NULL,
  primary_contact_name varchar(120),
  official_email varchar(254),
  plan_id uuid,
  licenses integer,
  created_on date,
  subdomain varchar(32),
  admin_email varchar(254),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_organizations_code UNIQUE (organization_code),
  CONSTRAINT ck_organizations_status CHECK (status IN ('Active', 'Trial', 'Suspended', 'Inactive'))
);
-- PlanFeatures — Child of plans — plan_features (from features[]: id, label, enabled)
CREATE TABLE plan_features (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id uuid NOT NULL,
  label varchar(120),
  enabled varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- Plan — Subscription plan (reference data).
CREATE TABLE plans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key varchar(20) NOT NULL,
  name varchar(40) NOT NULL,
  tagline varchar(200) NOT NULL,
  price numeric(14,2) NOT NULL,
  billing_period varchar(10),
  is_featured boolean,
  limits jsonb NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_plans_code UNIQUE (key),
  CONSTRAINT ck_plans_price_nonneg CHECK (price IS NULL OR price >= 0)
);
-- PlatformDocument — Guides, API references and release notes uploaded by the Seereon team.
CREATE TABLE platform_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  platform_document_code varchar(20) NOT NULL,
  title varchar(200) NOT NULL,
  kind varchar(20) NOT NULL,
  version varchar(12) NOT NULL,
  file_name varchar(255) NOT NULL,
  audience varchar(10) NOT NULL,
  uploaded_on date NOT NULL,
  uploaded_by varchar(120) NOT NULL,
  size_bytes bigint NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_platform_documents_code UNIQUE (platform_document_code),
  CONSTRAINT ck_platform_documents_kind CHECK (kind IN ('User guide', 'Admin guide', 'API', 'Release notes', 'Compliance', 'Training video')),
  CONSTRAINT ck_platform_documents_audience CHECK (audience IN ('Clients', 'Internal', 'Both'))
);
-- PlatformSettings — Singleton platform configuration: modules offered to new organisations, branding, security policy, localisation defaults.
CREATE TABLE platform_settings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  platform_setting_code bigint NOT NULL,
  offered_modules text NOT NULL,
  platform_name varchar(60) NOT NULL,
  support_email varchar(254) NOT NULL,
  primary_color char(7) NOT NULL,
  accent_color char(7) NOT NULL,
  enforce_mfa boolean NOT NULL,
  password_rotation_90d boolean NOT NULL,
  ip_allowlist_enabled boolean NOT NULL,
  session_timeout_30m boolean NOT NULL,
  default_timezone varchar(40) NOT NULL,
  default_currency char(3) NOT NULL,
  default_language varchar(30) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_platform_settings_code UNIQUE (platform_setting_code)
);
-- PlatformTicket — Client organisation → Seereon support queue.
CREATE TABLE platform_support_tickets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  platform_support_ticket_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  subject varchar(200) NOT NULL,
  requester_name varchar(120) NOT NULL,
  priority varchar(10) NOT NULL,
  status varchar(12) NOT NULL,
  assignee varchar(120) NOT NULL,
  updated_on date NOT NULL,
  description text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_platform_support_tickets_code UNIQUE (org_id, platform_support_ticket_code),
  CONSTRAINT ck_platform_support_tickets_priority CHECK (priority IN ('Critical', 'High', 'Medium', 'Low')),
  CONSTRAINT ck_platform_support_tickets_status CHECK (status IN ('Open', 'In Progress', 'Waiting', 'Resolved'))
);
-- PlatformTicketHistory — Child of platform_support_tickets — platform_ticket_history (from history[]: at date, by varchar, action text)
CREATE TABLE platform_ticket_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  platform_support_ticket_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RoutingRule — Default owner by issue type (unused by any screen).
CREATE TABLE support_routing_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  issue_type varchar(30) NOT NULL,
  default_owner varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_support_routing_rules_key UNIQUE (org_id, issue_type)
);
-- SlaRule — Target resolution hours by ticket severity (currently global and unused by any screen).
CREATE TABLE support_sla_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  severity varchar(10) NOT NULL,
  target_hours integer NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_support_sla_rules_key UNIQUE (org_id, severity),
  CONSTRAINT ck_support_sla_rules_severity CHECK (severity IN ('Critical', 'High', 'Medium', 'Low'))
);
-- DelegationEntry — Ticket reassignment history (unused by any screen).
CREATE TABLE support_ticket_delegations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  support_ticket_delegation_code varchar(20) NOT NULL,
  ticket_id uuid NOT NULL,
  from_owner varchar(120) NOT NULL,
  to_owner varchar(120) NOT NULL,
  reason text NOT NULL,
  reassigned_at timestamptz NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_support_ticket_delegations_code UNIQUE (org_id, support_ticket_delegation_code)
);
-- TenantCredential — Client Super Admin / entity Admin accounts provisioned by Seereon or by a Super Admin, with the temporary password lifecycle.
CREATE TABLE tenant_users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_user_code varchar(30) NOT NULL,
  email varchar(254) NOT NULL,
  name varchar(120) NOT NULL,
  role varchar(12) NOT NULL,
  org_id uuid NOT NULL,
  group_id uuid,
  temp_password_hash varchar(255) NOT NULL,
  force_password_change boolean NOT NULL,
  created_on date NOT NULL,
  created_by varchar(120) NOT NULL,
  shared_on date,
  shared_to varchar(254),
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_tenant_users_code UNIQUE (org_id, tenant_user_code),
  CONSTRAINT ck_tenant_users_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_tenant_users_role CHECK (role IN ('SuperAdmin', 'Admin'))
);

-- =============================================================================
-- Identity, Access & Administration
-- =============================================================================

-- Announcement — Announcement / notice / event / circular published into an entity; employees view, download and acknowledge.
CREATE TABLE announcements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  announcement_code bigint NOT NULL,
  code varchar(12) NOT NULL,
  type varchar(12) NOT NULL,
  subject varchar(200) NOT NULL,
  description text,
  valid_from date NOT NULL,
  valid_to date NOT NULL,
  attachment_name varchar(200),
  org_id uuid NOT NULL,
  published_by varchar(120),
  published_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_announcements_code UNIQUE (org_id, announcement_code),
  CONSTRAINT ck_announcements_type CHECK (type IN ('Announcement', 'Notice', 'Event', 'Circular')),
  CONSTRAINT ck_announcements_valid_to_after_valid_from CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);
-- AppRolePermission — Static permission model of the 11 app roles: screen routes (ROLE_NAV / ROLE_EMP_NAV, '*' = all) and action keys (ROLE_ACTIONS). Reference data, seeded.
CREATE TABLE app_role_permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  app_role varchar(12) NOT NULL,
  kind varchar(6) NOT NULL,
  permission_key varchar(80) NOT NULL,
  description text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_app_role_permissions_key UNIQUE (app_role, kind, permission_key),
  CONSTRAINT ck_app_role_permissions_app_role CHECK (app_role IN ('SuperAdmin', 'Admin', 'CEO', 'COO', 'CFO', 'CTO', 'CHRO', 'HR', 'HOD', 'Manager', 'Employee')),
  CONSTRAINT ck_app_role_permissions_kind CHECK (kind IN ('screen', 'action'))
);
-- ApprovalChainStep — Person-resolved approval chain embedded in Assets, Tours, Comp-off and Appraisals (HOD, reporting manager, HR partner or first holder of a role in the employee'
CREATE TABLE approval_chain_steps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  parent_type varchar(30) NOT NULL,
  parent_id uuid NOT NULL,
  seq smallint NOT NULL,
  role varchar(12) NOT NULL,
  label varchar(60) NOT NULL,
  approver_id uuid,
  approver_name varchar(120) NOT NULL,
  status varchar(8) NOT NULL,
  acted_on date,
  note text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_approval_chain_steps_key UNIQUE (parent_type, parent_id, seq),
  CONSTRAINT ck_approval_chain_steps_role CHECK (role IN ('SuperAdmin', 'Admin', 'CEO', 'COO', 'CFO', 'CTO', 'CHRO', 'HR', 'HOD', 'Manager', 'Employee', 'HRPartner')),
  CONSTRAINT ck_approval_chain_steps_status CHECK (status IN ('Pending', 'Approved', 'Rejected', 'Skipped'))
);
-- ApprovalRequestSteps — Child of approval_requests — approval_request_steps (request_id, level, approver_role, status, acted_by, acted_at date, remarks text)
CREATE TABLE approval_request_steps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  approval_request_id uuid NOT NULL,
  request_id varchar(120),
  level varchar(120),
  approver_role varchar(120),
  status varchar(120),
  acted_by varchar(120),
  acted_at date,
  remarks text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ApprovalRequest — A request travelling through a workflow level by level (inbox on /org/approvals).
CREATE TABLE approval_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  approval_request_code bigint NOT NULL,
  code varchar(10) NOT NULL,
  module varchar(30) NOT NULL,
  reference varchar(40) NOT NULL,
  title varchar(200) NOT NULL,
  requested_by uuid NOT NULL,
  requested_by_name varchar(120) NOT NULL,
  raised_on date NOT NULL,
  amount numeric(14,2),
  status varchar(10) NOT NULL,
  current_level smallint NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_approval_requests_code UNIQUE (org_id, approval_request_code),
  CONSTRAINT ck_approval_requests_amount_nonneg CHECK (amount IS NULL OR amount >= 0),
  CONSTRAINT ck_approval_requests_status CHECK (status IN ('Pending', 'Approved', 'Rejected', 'Rework'))
);
-- ApprovalWorkflowLevels — Child of approval_workflows — approval_workflow_levels (workflow_id, level smallint, approver_role varchar(20) enum APPROVER_ROLES, sla_days smallint >=1, optio
CREATE TABLE approval_workflow_levels (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  approval_workflow_id uuid NOT NULL,
  workflow_id varchar(120),
  level smallint,
  approver_role varchar(20),
  sla_days smallint,
  optional boolean,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ApprovalWorkflow — Configurable ordered approval chain per request type (one active per module).
CREATE TABLE approval_workflows (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  module varchar(30) NOT NULL,
  name varchar(120) NOT NULL,
  description text,
  active boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_approval_workflows_code UNIQUE (org_id, module),
  CONSTRAINT ck_approval_workflows_module CHECK (module IN ('Leave', 'Timesheets', 'Tasks', 'Goals', 'Performance Reviews', 'Training Completion', 'Expenses', 'Loan Requests', 'Salary Approvals', 'Finance Requests', 'Asset Requests'))
);
-- ArchiveConfig — Archive retention policy.
CREATE TABLE archive_settings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  auto_delete_enabled boolean NOT NULL,
  auto_delete_days smallint NOT NULL,
  notify_before_days smallint NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_archive_settings_key UNIQUE (org_id)
);
-- ArchivedRecord — System Archive / soft delete: deleted rows from any module with payload for restore and retention-based auto purge.
CREATE TABLE archived_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  archived_record_code varchar(40) NOT NULL,
  module varchar(40) NOT NULL,
  record_id varchar(40) NOT NULL,
  title varchar(200) NOT NULL,
  summary text,
  archived_at timestamptz NOT NULL,
  archived_by varchar(120) NOT NULL,
  reason text NOT NULL,
  payload jsonb,
  org_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_archived_records_code UNIQUE (org_id, archived_record_code)
);
-- BrandConfig — Document branding (name, logo, tagline, address, contact, footer, accent) — group default row (org_id null) plus per-entity overrides.
CREATE TABLE brand_profiles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  brand_profile_code bigint NOT NULL,
  org_id uuid,
  name varchar(160) NOT NULL,
  tagline varchar(200),
  logo_url text,
  address text,
  email citext,
  phone varchar(20),
  website varchar(120),
  footer text,
  accent_hex char(7),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_brand_profiles_code UNIQUE (org_id, brand_profile_code),
  CONSTRAINT ck_brand_profiles_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$')
);
-- DelegationEvents — Child of delegations — delegation_events (delegation_id, at, by, action)
CREATE TABLE delegation_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  delegation_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- DelegationModules — Child of delegations — delegation_modules (delegation_id, module varchar(40))
CREATE TABLE delegation_modules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  delegation_id uuid NOT NULL,
  module varchar(40),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- Delegation — Time-bound hand-over of module responsibilities from one employee to another at a permission level, optionally approval-gated; auto-expires.
CREATE TABLE delegations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  delegation_code bigint NOT NULL,
  code varchar(10) NOT NULL,
  from_user_id uuid NOT NULL,
  from_name varchar(120) NOT NULL,
  to_user_id uuid NOT NULL,
  to_name varchar(120) NOT NULL,
  level varchar(12) NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  reason text,
  status varchar(16) NOT NULL,
  requires_approval boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_delegations_code UNIQUE (org_id, delegation_code),
  CONSTRAINT ck_delegations_level CHECK (level IN ('View Only', 'Create', 'Edit', 'Approve', 'Full Control')),
  CONSTRAINT ck_delegations_status CHECK (status IN ('Pending Approval', 'Active', 'Expired', 'Revoked', 'Rejected')),
  CONSTRAINT ck_delegations_end_date_after_start_date CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);
-- OrgSecuritySettings — Per-entity security & notification-channel toggles (Settings → Security / Notifications).
CREATE TABLE org_security_settings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  mfa_admins boolean NOT NULL,
  session_timeout varchar(20) NOT NULL,
  ip_allow_list_enabled boolean NOT NULL,
  channel_email boolean NOT NULL,
  channel_whatsapp boolean NOT NULL,
  channel_sms boolean NOT NULL,
  channel_in_app boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_org_security_settings_key UNIQUE (org_id)
);
-- OrgTheme — Entity colour palette applied system-wide (Super Admin / Admin).
CREATE TABLE org_themes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  primary_hex char(7) NOT NULL,
  primary_dark_hex char(7) NOT NULL,
  accent_hex char(7) NOT NULL,
  radius varchar(8) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_org_themes_key UNIQUE (org_id),
  CONSTRAINT ck_org_themes_radius CHECK (radius IN ('compact', 'regular', 'rounded'))
);
-- OrgUserRecord — User Assignment / Branch Access list: a user (by e-mail) with role names per branch. Kept in sync with rbac_role_assignments when the e-mail is a real login.
CREATE TABLE org_user_access (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  name varchar(120) NOT NULL,
  email citext NOT NULL,
  status varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_org_user_access_code UNIQUE (org_id, email),
  CONSTRAINT ck_org_user_access_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_org_user_access_status CHECK (status IN ('Active', 'Invited', 'Suspended'))
);
-- OrgUserBranchRoles — Child of org_user_access — org_user_branch_roles (org_user_id, branch_id, role_id → rbac_roles.id)
CREATE TABLE org_user_branch_roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_user_acce_id uuid NOT NULL,
  org_user_id varchar(120),
  branch_id varchar(120),
  role_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- PasswordResetRequest — Forgot-password OTP request (6-digit code, 5-minute expiry).
CREATE TABLE password_reset_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  email citext NOT NULL,
  otp_hash varchar(128) NOT NULL,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_password_reset_requests_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$')
);
-- RbacRoleAssignments — Child of rbac_roles — rbac_role_assignments (role_id, user_id → users.id, branch_id) — from assignedUsers
CREATE TABLE rbac_role_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  rbac_role_id uuid NOT NULL,
  role_id uuid,
  user_id uuid,
  branch_id varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RbacRoleBranches — Child of rbac_roles — rbac_role_branches (role_id, branch_id)
CREATE TABLE rbac_role_branches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  rbac_role_id uuid NOT NULL,
  role_id uuid,
  branch_id varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RbacRoleEvents — Child of rbac_roles — rbac_role_events (role_id, at, by, action) — from history
CREATE TABLE rbac_role_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  rbac_role_id uuid NOT NULL,
  role_id uuid,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RbacRoleScreenPermissions — Child of rbac_roles — rbac_role_screen_permissions (role_id, screen_id → rbac_screens.id, can_view, can_edit, can_delete) — from permissions
CREATE TABLE rbac_role_screen_permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  rbac_role_id uuid NOT NULL,
  role_id uuid,
  screen_id uuid,
  can_view boolean,
  can_edit boolean,
  can_delete boolean,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RoleDef — Custom / built-in RBAC role designed in Roles & Permissions: screen-level View/Edit/Delete, branch scope and per-branch user assignments.
CREATE TABLE rbac_roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(80) NOT NULL,
  description text,
  user_count integer NOT NULL,
  screen_count integer NOT NULL,
  status varchar(6) NOT NULL,
  updated_on date NOT NULL,
  built_in boolean,
  created_by varchar(120),
  created_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_rbac_roles_status CHECK (status IN ('Active', 'Draft'))
);
-- RbacScreen — Catalogue of module → submodule → screen used by role design, temporary access and the permission matrix (screenId = module.submodule.screen).
CREATE TABLE rbac_screens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  rbac_screen_code varchar(80) NOT NULL,
  module_key varchar(40) NOT NULL,
  module_name varchar(80) NOT NULL,
  submodule_key varchar(40) NOT NULL,
  submodule_name varchar(80) NOT NULL,
  screen_name varchar(80) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_rbac_screens_code UNIQUE (rbac_screen_code)
);
-- ReportingLink — Reporting / functional manager per employee used to scope manager views (subtree).
CREATE TABLE reporting_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  reporting_manager_id uuid,
  functional_manager_id uuid,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_reporting_lines_key UNIQUE (employee_id)
);
-- SignInPolicy — Company sign-in policy: password rules (enforced by passwordPolicyError), lock-out threshold (enforced by recordFailedSignIn), MFA, session and SSO preferences.
CREATE TABLE signin_policies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  min_length smallint NOT NULL,
  require_upper boolean NOT NULL,
  require_number boolean NOT NULL,
  require_symbol boolean NOT NULL,
  expiry_days smallint NOT NULL,
  lock_after_attempts smallint NOT NULL,
  lock_minutes smallint NOT NULL,
  mfa_admins boolean NOT NULL,
  mfa_all boolean NOT NULL,
  session_idle_minutes smallint NOT NULL,
  remember_device_days smallint NOT NULL,
  prefer_sso boolean NOT NULL,
  updated_on date,
  updated_by varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_signin_policies_key UNIQUE (org_id)
);
-- TemporaryAccessGrantScreens — Child of temporary_access_grants — temporary_access_grant_screens (grant_id, screen_id → rbac_screens.id, can_view, can_edit, can_delete)
CREATE TABLE temporary_access_grant_screens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  temporary_access_grant_id uuid NOT NULL,
  grant_id uuid,
  screen_id uuid,
  can_view boolean,
  can_edit boolean,
  can_delete boolean,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- TempGrant — Time-boxed screen permissions for a user on a branch; auto-expire after 'to'.
CREATE TABLE temporary_access_grants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  temporary_access_grant_code bigint NOT NULL,
  code varchar(10) NOT NULL,
  user_id uuid NOT NULL,
  branch_id varchar(80),
  valid_from date NOT NULL,
  valid_to date NOT NULL,
  reason text,
  status varchar(8) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_temporary_access_grants_code UNIQUE (org_id, temporary_access_grant_code),
  CONSTRAINT ck_temporary_access_grants_status CHECK (status IN ('Active', 'Revoked')),
  CONSTRAINT ck_temporary_access_grants_valid_to_after_valid_from CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);
-- EmployeeAlert — In-app bell notifications per person (role granted, password reset, delegation, announcement, comp-off, leave, loan …).
CREATE TABLE user_alerts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_alert_code bigint NOT NULL,
  code varchar(12) NOT NULL,
  user_id uuid NOT NULL,
  created_at timestamptz NOT NULL,
  title varchar(200) NOT NULL,
  body text NOT NULL,
  kind varchar(10) NOT NULL,
  link varchar(200),
  read boolean NOT NULL,
  org_id uuid NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_user_alerts_code UNIQUE (org_id, user_alert_code),
  CONSTRAINT ck_user_alerts_kind CHECK (kind IN ('leave', 'compoff', 'payroll', 'loan', 'grievance', 'review', 'general'))
);
-- PasswordCredential — Self-service / admin-set password override per user (UI keeps a plain map in localStorage; production: hash + metadata).
CREATE TABLE user_credentials (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  password_hash varchar(255) NOT NULL,
  set_by uuid,
  updated_at timestamptz NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_user_credentials_key UNIQUE (user_id)
);
-- UserLoginEvents — Child of user_logins — user_login_events (user_id, at date/timestamptz, by varchar, action text) — flattened from history[]
CREATE TABLE user_login_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_login_id uuid NOT NULL,
  user_id uuid,
  action_at timestamptz,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- LoginRecord — Account state per user for Users & Logins: status, MFA, lock-out counter, last sign-in, sessions, reset-pending flag and an audit history.
CREATE TABLE user_logins (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  status varchar(10) NOT NULL,
  mfa_enforced boolean NOT NULL,
  last_login_at timestamptz,
  last_ip inet,
  last_device varchar(80),
  failed_attempts smallint NOT NULL,
  password_changed_on date,
  must_reset_password boolean NOT NULL,
  active_sessions smallint NOT NULL,
  invited_on date,
  invited_by varchar(120),
  notes text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_user_logins_key UNIQUE (user_id),
  CONSTRAINT ck_user_logins_status CHECK (status IN ('Active', 'Invited', 'Suspended', 'Locked'))
);
-- UserPrefs — Per-user personalisation: font, wallpaper (+blur/dim/glass), avatar photo or generated style.
CREATE TABLE user_preferences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  font varchar(10) NOT NULL,
  wallpaper varchar(40),
  blur_px smallint NOT NULL,
  dim_pct smallint NOT NULL,
  glass boolean NOT NULL,
  avatar_url text,
  avatar_style varchar(10) NOT NULL,
  avatar_seed integer NOT NULL,
  language varchar(5) NOT NULL,
  timezone varchar(60) NOT NULL,
  date_format varchar(12) NOT NULL,
  notification_prefs jsonb,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_user_preferences_key UNIQUE (user_id),
  CONSTRAINT ck_user_preferences_font CHECK (font IN ('inter', 'manrope', 'plex', 'source', 'roboto', 'nunito', 'dmsans', 'system')),
  CONSTRAINT ck_user_preferences_avatar_style CHECK (avatar_style IN ('photo', 'initials', 'gradient', 'pattern')),
  CONSTRAINT ck_user_preferences_date_format CHECK (date_format IN ('DD/MM/YYYY', 'MM/DD/YYYY', 'YYYY-MM-DD'))
);
-- ActiveScope — Working scope per signed-in user: active entity, Super Admin group/entity view, active branch (restored on reload).
CREATE TABLE user_scope_preferences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  active_org_id uuid NOT NULL,
  view_scope varchar(6) NOT NULL,
  active_branch_id varchar(80),
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_user_scope_preferences_key UNIQUE (user_id),
  CONSTRAINT ck_user_scope_preferences_view_scope CHECK (view_scope IN ('group', 'entity'))
);
-- UserSession — Signed-in identity for the browser (UI: seereon.session.user holds the user id; signOut clears it). Production: server session / refresh token.
CREATE TABLE user_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  device varchar(120),
  ip inet,
  created_at timestamptz NOT NULL,
  revoked_at timestamptz,
  active_org_id uuid NOT NULL,
  view_scope varchar(6) NOT NULL,
  org_id uuid NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_user_sessions_view_scope CHECK (view_scope IN ('group', 'entity'))
);
-- UserWallpapers — Child of user_preferences — user_wallpapers (id varchar(20) PK 'wp-…', user_id, name, image_url, added_on date)
CREATE TABLE user_wallpapers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_preference_id uuid NOT NULL,
  user_id uuid,
  name varchar(120),
  image_url varchar(120),
  added_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- AppUser — Every sign-in account: client group Super Admin, entity Admins, CXOs, HR, HODs, managers, employees (seeded roster), invited users and Seereon platform staff. T
CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  name varchar(120) NOT NULL,
  email citext NOT NULL,
  app_role varchar(12) NOT NULL,
  designation varchar(120) NOT NULL,
  department_id uuid NOT NULL,
  branch varchar(80) NOT NULL,
  phone varchar(20),
  manager_id uuid,
  hr_partner_id uuid,
  date_of_joining date NOT NULL,
  group_date_of_joining date,
  org_id uuid NOT NULL,
  group_id uuid,
  landing_portal varchar(3) NOT NULL,
  password_hash varchar(255) NOT NULL,
  invited_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_users_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_users_app_role CHECK (app_role IN ('SuperAdmin', 'Admin', 'CEO', 'COO', 'CFO', 'CTO', 'CHRO', 'HR', 'HOD', 'Manager', 'Employee')),
  CONSTRAINT ck_users_landing_portal CHECK (landing_portal IN ('org', 'emp', 'app'))
);

-- =============================================================================
-- Employees & Organisation
-- =============================================================================

-- AnnouncementAcknowledgement — Read acknowledgement of a circular / announcement.
CREATE TABLE announcement_acknowledgements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  announcement_acknowledgement_code varchar(10) NOT NULL,
  announcement_id uuid NOT NULL,
  emp_id uuid NOT NULL,
  employee varchar(120) NOT NULL,
  acknowledged_at timestamptz NOT NULL,
  notified_hr boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_announcement_acknowledgements_code UNIQUE (org_id, announcement_acknowledgement_code)
);
-- BuildingBlocks — Child of buildings — building_blocks (id, name, building_id, floors)
CREATE TABLE building_blocks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  building_id uuid NOT NULL,
  name varchar(120),
  floors varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- BuildingFloors — Child of buildings — building_floors (id, name, building_id, block_id, seats, occupied; occupied ≤ seats)
CREATE TABLE building_floors (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  building_id uuid NOT NULL,
  name varchar(120),
  block_id varchar(120),
  seats varchar(120),
