  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- Building — Buildings / blocks / floors under a branch (seat planning).
CREATE TABLE buildings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  building_code varchar(10) NOT NULL,
  name varchar(80) NOT NULL,
  organization_branch_id uuid NOT NULL,
  floors smallint NOT NULL,
  blocks smallint NOT NULL,
  capacity integer NOT NULL,
  notes text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_buildings_code UNIQUE (org_id, building_code)
);
-- Department — Department master with Head of Department; every HOD routing reads it.
CREATE TABLE departments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  department_code varchar(10) NOT NULL,
  name varchar(80) NOT NULL,
  code varchar(10) NOT NULL,
  hod_id uuid,
  cost_centre varchar(20) NOT NULL,
  organization_branch_id uuid NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_departments_code UNIQUE (org_id, department_code)
);
-- Designation — Designation master (level, grade, band) per entity; drives record form, promotions and transfers.
CREATE TABLE designations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  designation_code varchar(10) NOT NULL,
  level smallint NOT NULL,
  name varchar(80) NOT NULL,
  grade varchar(10) NOT NULL,
  band varchar(12) NOT NULL,
  department varchar(80),
  description text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_designations_code UNIQUE (org_id, designation_code),
  CONSTRAINT ck_designations_band CHECK (band IN ('Entry', 'Mid', 'Senior', 'Executive'))
);
-- EmployeeBankAccount — Salary account captured on the employee record form.
CREATE TABLE employee_bank_accounts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  holder_name varchar(120) NOT NULL,
  bank_name varchar(80) NOT NULL,
  account_no varchar(18) NOT NULL,
  ifsc char(11) NOT NULL,
  mode varchar(40) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employee_bank_accounts_key UNIQUE (employee_id),
  CONSTRAINT ck_employee_bank_accounts_ifsc_fmt CHECK (ifsc IS NULL OR ifsc ~ '^[A-Z]{4}0[A-Z0-9]{6}$'),
  CONSTRAINT ck_employee_bank_accounts_mode CHECK (mode IN ('NEFT', 'IMPS', 'RTGS'))
);
-- EmployeeCompensation — Current CTC and grade (set at hire, changed by promotion/appraisal).
CREATE TABLE employee_compensation (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  ctc numeric(14,2) NOT NULL,
  salary_structure_id uuid NOT NULL,
  wage_type varchar(20) NOT NULL,
  effective_from date,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employee_compensation_key UNIQUE (employee_id),
  CONSTRAINT ck_employee_compensation_ctc_nonneg CHECK (ctc IS NULL OR ctc >= 0)
);
-- EmployeeCompensationHistory — Child of employee_compensation — employee_compensation_history (one row per promotion / increment)
CREATE TABLE employee_compensation_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_compensation_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- EmployeeJob — Job & personal details of an employee (profile tabs): DOJ, probation, employment type, grade/wage type, reporting manager, DOB, gender.
CREATE TABLE employee_job (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  date_of_joining date NOT NULL,
  confirmation_date date,
  employment_type varchar(20) NOT NULL,
  probation_months smallint NOT NULL,
  notice_period_days smallint NOT NULL,
  salary_structure_id uuid NOT NULL,
  wage_type varchar(20) NOT NULL,
  reporting_manager_id uuid,
  hr_partner_id uuid,
