  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employee_job_key UNIQUE (employee_id),
  CONSTRAINT ck_employee_job_employment_type CHECK (employment_type IN ('Full-time', 'Part-time', 'Contract', 'Intern')),
  CONSTRAINT ck_employee_job_wage_type CHECK (wage_type IN ('Salaried', 'Monthly wage', 'Daily wage')),
  CONSTRAINT ck_employee_job_personal_email_fmt CHECK (personal_email IS NULL OR personal_email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$')
);
-- EmployeeStatutoryIds — PAN / UAN / PF member id / ESI IP number captured on the record form or fixed from payroll checks.
CREATE TABLE employee_statutory_ids (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
