  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employee_statutory_ids_key UNIQUE (employee_id),
  CONSTRAINT ck_employee_statutory_ids_pan_fmt CHECK (pan IS NULL OR pan ~ '^[A-Z]{5}[0-9]{4}[A-Z]$'),
  CONSTRAINT ck_employee_statutory_ids_uan_fmt CHECK (uan IS NULL OR uan ~ '^[0-9]{12}$')
);
-- Employee — Directory row of every employee (seeded roster + new hires); the single source for lists, pickers and sign-in mapping.
CREATE TABLE employees (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_code varchar(20) NOT NULL,
  name varchar(120) NOT NULL,
  email varchar(160) NOT NULL,
  phone varchar(20) NOT NULL,
  department_id uuid NOT NULL,
  role varchar(120) NOT NULL,
  organization_branch_id uuid NOT NULL,
  status varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employees_code UNIQUE (org_id, employee_code),
  CONSTRAINT ck_employees_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_employees_status CHECK (status IN ('Active', 'On Leave', 'Notice', 'Exited', 'Retired'))
);
-- HrPartnerAssignment — HR business partner owning an employee's HR approvals.
CREATE TABLE hr_partner_assignments (
