);
-- SubstituteManager — Delegated manager duties for a period.
CREATE TABLE manager_substitutes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  manager_substitute_code varchar(10) NOT NULL,
  manager_id uuid NOT NULL,
  substitute_id uuid NOT NULL,
  scope varchar(40) NOT NULL,
  from_date date NOT NULL,
  to_date date NOT NULL,
  reason text NOT NULL,
  status varchar(8) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_manager_substitutes_code UNIQUE (org_id, manager_substitute_code),
  CONSTRAINT ck_manager_substitutes_status CHECK (status IN ('Active', 'Expired')),
  CONSTRAINT ck_manager_substitutes_to_date_after_from_date CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date)
);
-- PromotionCaseApprovals — Child of promotion_cases — promotion_case_approvals (step, by, on, decision Approved|Rejected, note)
CREATE TABLE promotion_case_approvals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_case_id uuid NOT NULL,
  step varchar(120),
  action_by varchar(120),
  action_on date,
  decision varchar(120),
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_promotion_case_approvals_decision CHECK (decision IN ('Approved', 'Rejected'))
);
-- PromotionCaseAttachments — Child of promotion_cases — promotion_case_attachments (file_name)
CREATE TABLE promotion_case_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_case_id uuid NOT NULL,
  file_name varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- PromotionCaseHistory — Child of promotion_cases — promotion_case_history (at, by, action)
CREATE TABLE promotion_case_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_case_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
