  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- PromotionCase — Promotion / increment / appraisal outcome with 2-step approval and generated letter.
CREATE TABLE promotion_cases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_case_code varchar(20) NOT NULL,
  emp_id uuid NOT NULL,
  employee varchar(120) NOT NULL,
  dept varchar(80) NOT NULL,
  purpose varchar(60) NOT NULL,
  self_appraisal_id uuid,
  basis text NOT NULL,
  from_designation varchar(120) NOT NULL,
  to_designation varchar(120) NOT NULL,
  from_grade varchar(10) NOT NULL,
  salary_structure_id uuid NOT NULL,
  from_ctc numeric(14,2) NOT NULL,
  to_ctc numeric(14,2) NOT NULL,
  hike_pct numeric(6,2) NOT NULL,
  effective_from date NOT NULL,
  new_manager varchar(120),
  new_branch varchar(80),
  probation_months smallint NOT NULL,
  recommended_by varchar(120),
  letter_type varchar(20) NOT NULL,
  letter_mode varchar(24) NOT NULL,
  letter_body text,
  letter_ref varchar(30),
  letter_file varchar(200),
  status varchar(20) NOT NULL,
  created_on date NOT NULL,
  created_by varchar(120) NOT NULL,
  remarks text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_promotion_cases_code UNIQUE (org_id, promotion_case_code),
  CONSTRAINT ck_promotion_cases_from_ctc_nonneg CHECK (from_ctc IS NULL OR from_ctc >= 0),
  CONSTRAINT ck_promotion_cases_to_ctc_nonneg CHECK (to_ctc IS NULL OR to_ctc >= 0),
  CONSTRAINT ck_promotion_cases_hike_pct_pct CHECK (hike_pct IS NULL OR (hike_pct >= 0 AND hike_pct <= 100)),
  CONSTRAINT ck_promotion_cases_letter_type CHECK (letter_type IN ('Promotion Letter', 'Increment Letter', 'Appointment Letter')),
  CONSTRAINT ck_promotion_cases_letter_mode CHECK (letter_mode IN ('Generate from template', 'Attach signed letter')),
  CONSTRAINT ck_promotion_cases_status CHECK (status IN ('Draft', 'Pending approval', 'Approved', 'Effective', 'Rejected'))
);
-- TerminationCaseApprovals — Child of termination_cases — termination_case_approvals (step, by, on, decision Approved|Rejected, note)
CREATE TABLE termination_case_approvals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
