-- TransferCase — Branch / department / manager / project / role transfer with HR approval and letter.
CREATE TABLE transfer_cases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  transfer_case_code varchar(20) NOT NULL,
  emp_id uuid NOT NULL,
  employee varchar(120) NOT NULL,
  type varchar(20) NOT NULL,
  from_branch varchar(80) NOT NULL,
  to_branch varchar(80) NOT NULL,
  from_dept varchar(80) NOT NULL,
  to_dept varchar(80) NOT NULL,
