  CONSTRAINT ck_transfer_cases_requested_by CHECK (requested_by IN ('Employee', 'Manager', 'HR', 'Management')),
  CONSTRAINT ck_transfer_cases_status CHECK (status IN ('Pending approval', 'Approved', 'Effective', 'Rejected'))
);
-- WarningCaseEvidence — Child of warning_cases — warning_case_evidence
CREATE TABLE warning_case_evidence (
