-- =============================================================================
-- Recruitment & Onboarding
-- =============================================================================

-- ApplicantAtsReasons — Child of applicants — applicant_ats_reasons (reason)
CREATE TABLE applicant_ats_reasons (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  applicant_id uuid NOT NULL,
