  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- Applicant — Candidate for a job post; moves Applied → Shortlisted → Interviewing → Finalised → Offered → Onboarding (or Rejected).
CREATE TABLE applicants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  applicant_code varchar(10) NOT NULL,
  job_id uuid NOT NULL,
  job_title varchar(120) NOT NULL,
  name varchar(120) NOT NULL,
  email varchar(160) NOT NULL,
  phone varchar(20),
  source varchar(30) NOT NULL,
  current_company varchar(120),
  experience_years numeric(4,1) NOT NULL,
  current_ctc numeric(14,2) NOT NULL,
  expected_ctc numeric(14,2) NOT NULL,
  education varchar(160),
  notice_days smallint NOT NULL,
  location varchar(80),
  cv_file varchar(200),
  cover_note text,
  applied_on date NOT NULL,
  stage varchar(12) NOT NULL,
  ats_score smallint,
  ats_remarks text,
  ats_ran_at date,
  shortlist_by varchar(120),
  shortlist_how varchar(6),
  shortlist_on date,
  current_round varchar(40),
  finalised_on date,
  finalised_by varchar(120),
  offer_id uuid,
  rejected_reason text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_applicants_code UNIQUE (org_id, applicant_code),
  CONSTRAINT ck_applicants_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_applicants_current_ctc_nonneg CHECK (current_ctc IS NULL OR current_ctc >= 0),
  CONSTRAINT ck_applicants_expected_ctc_nonneg CHECK (expected_ctc IS NULL OR expected_ctc >= 0),
  CONSTRAINT ck_applicants_stage CHECK (stage IN ('Applied', 'Shortlisted', 'Interviewing', 'Finalised', 'Offered', 'Onboarding', 'Rejected')),
  CONSTRAINT ck_applicants_shortlist_how CHECK (shortlist_how IN ('Auto', 'Manual'))
);
-- AssessmentParamAppliesTo — Child of assessment_params — assessment_param_applies_to (job_family)
CREATE TABLE assessment_param_applies_to (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  assessment_param_id uuid NOT NULL,
  job_family varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- AssessmentParam — Weighted parameter used in candidate scorecards.
CREATE TABLE assessment_params (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  assessment_param_code varchar(8) NOT NULL,
  name varchar(80) NOT NULL,
  param_group varchar(20) NOT NULL,
  weight numeric(5,2) NOT NULL,
  scale smallint NOT NULL,
  description text,
  mandatory boolean NOT NULL,
  active boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_assessment_params_code UNIQUE (org_id, assessment_param_code),
  CONSTRAINT ck_assessment_params_param_group CHECK (param_group IN ('Technical', 'Behavioural', 'Aptitude', 'Attitude', 'Communication', 'Leadership', 'Domain', 'Culture fit'))
);
-- CareerSettings — Careers-portal branding, about-company and plain offer template per entity.
CREATE TABLE career_settings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  career_setting_code bigint NOT NULL,
  org_id uuid NOT NULL,
  title varchar(120) NOT NULL,
  footer varchar(200) NOT NULL,
  mission text NOT NULL,
  size varchar(20) NOT NULL,
  industry varchar(80) NOT NULL,
  offer_template text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_career_settings_code UNIQUE (org_id, career_setting_code)
);
-- Interview — Scheduled interview round with mode, panel, feedback and result.
CREATE TABLE interviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  interview_code varchar(12) NOT NULL,
  applicant_id uuid NOT NULL,
  round varchar(40) NOT NULL,
  type varchar(40) NOT NULL,
  mode varchar(10) NOT NULL,
  date date NOT NULL,
  time time NOT NULL,
  duration_min smallint NOT NULL,
  panel varchar(200) NOT NULL,
  link varchar(300),
  venue varchar(200),
  status varchar(10) NOT NULL,
  scheduled_by varchar(120) NOT NULL,
  scheduled_on date NOT NULL,
  feedback text,
  result varchar(24),
  scorecard_id uuid,
  completed_on date,
  completed_by varchar(120),
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
