  CONSTRAINT ck_interviews_status CHECK (status IN ('Scheduled', 'Completed', 'No-show', 'Cancelled')),
  CONSTRAINT ck_interviews_result CHECK (result IN ('Proceed to next round', 'Fit for the job', 'Reject', 'Hold'))
);
-- JobPost — Opening with JD, band, skills (ATS input) and status.
CREATE TABLE job_posts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  job_post_code varchar(10) NOT NULL,
