  CONSTRAINT ck_job_posts_min_salary_nonneg CHECK (min_salary IS NULL OR min_salary >= 0),
  CONSTRAINT ck_job_posts_max_salary_nonneg CHECK (max_salary IS NULL OR max_salary >= 0),
  CONSTRAINT ck_job_posts_status CHECK (status IN ('Open', 'On hold', 'Closed'))
);
-- NewHire — Hire record created by the record form, Hire/Re-hire dialog or the welcome e-mail; provisions directory row + login.
