  phone varchar(20),
  dob date,
  gender varchar(20),
  org_id uuid NOT NULL,
  branch varchar(80) NOT NULL,
  dept varchar(80) NOT NULL,
  designation varchar(120) NOT NULL,
  role varchar(12) NOT NULL,
  employment_type varchar(12) NOT NULL,
  manager_id uuid,
  doj date NOT NULL,
  probation_months smallint NOT NULL,
  ctc numeric(14,2) NOT NULL,
  pattern_id uuid,
  salary_structure_id uuid,
  wage_type varchar(20),
  status varchar(10) NOT NULL,
  rehire_of_id uuid,
  created_on date NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_new_hires_code UNIQUE (org_id, new_hire_code),
  CONSTRAINT ck_new_hires_personal_email_fmt CHECK (personal_email IS NULL OR personal_email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_new_hires_work_email_fmt CHECK (work_email IS NULL OR work_email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_new_hires_role CHECK (role IN ('Employee', 'Manager', 'HOD', 'HR', 'CTO', 'CFO', 'COO', 'CHRO')),
  CONSTRAINT ck_new_hires_employment_type CHECK (employment_type IN ('Full-time', 'Part-time', 'Contract', 'Intern')),
  CONSTRAINT ck_new_hires_ctc_nonneg CHECK (ctc IS NULL OR ctc >= 0),
  CONSTRAINT ck_new_hires_wage_type CHECK (wage_type IN ('Salaried', 'Monthly wage', 'Daily wage')),
  CONSTRAINT ck_new_hires_status CHECK (status IN ('Active', 'Re-hired'))
);
-- OfferComponents — Child of offers — offer_components (label, monthly) — HR-edited salary structure
CREATE TABLE offer_components (
