);
-- OfferHistory — Child of offers — offer_history (at, by, action)
CREATE TABLE offer_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  offer_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- Offer — Offer lifecycle: letter, secure candidate link, e-sign, document upload & verification, welcome e-mail that provisions the employee.
CREATE TABLE offers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  offer_code varchar(20) NOT NULL,
  candidate_id uuid NOT NULL,
  candidate varchar(120) NOT NULL,
  email varchar(160) NOT NULL,
  phone varchar(20),
  position varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  salary_structure_id uuid NOT NULL,
  branch varchar(80) NOT NULL,
  ctc numeric(14,2) NOT NULL,
  joining_date date NOT NULL,
  expiry_date date NOT NULL,
  template_id uuid NOT NULL,
  letter_body text,
  status varchar(16) NOT NULL,
  token char(16) NOT NULL,
  sent_at timestamptz,
  viewed_at timestamptz,
  accepted_at timestamptz,
  signature varchar(120),
  decline_reason text,
  verified_by varchar(120),
  verified_at timestamptz,
  welcome_sent_at timestamptz,
  employee_id uuid,
  work_email varchar(160),
  temp_password text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_offers_code UNIQUE (org_id, offer_code),
  CONSTRAINT ck_offers_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_offers_ctc_nonneg CHECK (ctc IS NULL OR ctc >= 0),
  CONSTRAINT ck_offers_status CHECK (status IN ('Draft', 'Sent', 'Viewed', 'Accepted', 'Declined', 'Docs Submitted', 'Verified', 'Welcome Sent', 'Joined', 'Expired')),
  CONSTRAINT ck_offers_work_email_fmt CHECK (work_email IS NULL OR work_email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$')
);
-- ReferralCaseHistory — Child of referral_cases — referral_case_history
CREATE TABLE referral_case_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  referral_case_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ReferralCase — Employee referral; creates an applicant (source Referral) and tracks bonus.
CREATE TABLE referral_cases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  referral_case_code varchar(20) NOT NULL,
  referrer_id uuid NOT NULL,
  referrer varchar(120) NOT NULL,
