  candidate varchar(120) NOT NULL,
  email varchar(160) NOT NULL,
  phone varchar(20),
  relationship varchar(40) NOT NULL,
  job_id uuid NOT NULL,
  job_title varchar(120) NOT NULL,
  cv_file varchar(200),
  skills text,
  experience_years numeric(4,1) NOT NULL,
  note text,
  applicant_id uuid,
  bonus_eligible boolean NOT NULL,
  bonus_amount numeric(14,2) NOT NULL,
  bonus_paid_on date,
  status varchar(14) NOT NULL,
  created_on date NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_referral_cases_code UNIQUE (org_id, referral_case_code),
  CONSTRAINT ck_referral_cases_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_referral_cases_bonus_amount_nonneg CHECK (bonus_amount IS NULL OR bonus_amount >= 0),
  CONSTRAINT ck_referral_cases_status CHECK (status IN ('Submitted', 'Screening', 'Interviewing', 'Hired', 'Bonus paid', 'Not selected'))
);
-- RequiredDocument — Documents a candidate uploads on the offer link.
CREATE TABLE required_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key varchar(20) NOT NULL,
  label varchar(80) NOT NULL,
  mandatory boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_required_documents_code UNIQUE (key)
);
-- ScorecardScores — Child of scorecards — scorecard_scores (param_id → assessment_params.id, score, note)
CREATE TABLE scorecard_scores (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scorecard_id uuid NOT NULL,
  param_id uuid,
  score varchar(120),
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- Scorecard — Assessment of a candidate for one round; weighted % computed from params.
CREATE TABLE scorecards (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  scorecard_code varchar(10) NOT NULL,
  candidate_id uuid NOT NULL,
  candidate varchar(120) NOT NULL,
  round varchar(40) NOT NULL,
  assessor varchar(120) NOT NULL,
  assessed_on date NOT NULL,
  weighted_pct numeric(5,2) NOT NULL,
  recommendation varchar(12) NOT NULL,
  remarks text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_scorecards_code UNIQUE (org_id, scorecard_code),
  CONSTRAINT ck_scorecards_weighted_pct_pct CHECK (weighted_pct IS NULL OR (weighted_pct >= 0 AND weighted_pct <= 100)),
  CONSTRAINT ck_scorecards_recommendation CHECK (recommendation IN ('Strong hire', 'Proceed', 'Hold', 'Reject'))
);

