  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_geofence_rules_code UNIQUE (org_id, geofence_rule_code)
);
-- HandbookAcknowledgement — Employee e-signature of a handbook version.
CREATE TABLE handbook_acknowledgements (
