  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_handbook_acknowledgements_key UNIQUE (emp_id, handbook_version_id)
);
-- HandbookVersion — Published Employee Handbook versions.
CREATE TABLE handbook_versions (
