);
-- Holiday — Read view of National / State / Optional holidays for a branch (maintained in Master Data).
CREATE TABLE holiday_calendar_days (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  holiday_calendar_day_code varchar(24) NOT NULL,
  name varchar(120) NOT NULL,
  holiday_date date NOT NULL,
  type varchar(12) NOT NULL,
  paid boolean NOT NULL,
  calendar_name varchar(120) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_holiday_calendar_days_code UNIQUE (org_id, holiday_calendar_day_code),
  CONSTRAINT ck_holiday_calendar_days_type CHECK (type IN ('Public', 'Festival', 'Optional'))
);
-- HolidayCalendar — National / regional / optional holiday calendar assigned to branches.
CREATE TABLE holiday_calendars (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  holiday_calendar_code varchar(20) NOT NULL,
  name varchar(80) NOT NULL,
  type varchar(24) NOT NULL,
  year smallint NOT NULL,
  applies_to text,
  uploaded_file varchar(200),
  active boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_holiday_calendars_code UNIQUE (org_id, holiday_calendar_code),
  CONSTRAINT ck_holiday_calendars_type CHECK (type IN ('National', 'Regional / State', 'Optional / Restricted'))
);
-- Holidays — Child of holiday_calendars — holidays (calendar_id, date, name) — unique (calendar_id, date); date within year
CREATE TABLE holidays (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  holiday_calendar_id uuid NOT NULL,
  calendar_id uuid,
  date date,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- InsurancePlan — ESI / group mediclaim / term life plan master.
CREATE TABLE insurance_plans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  insurance_plan_code varchar(8) NOT NULL,
  name varchar(80) NOT NULL,
  kind varchar(20) NOT NULL,
  provider varchar(80) NOT NULL,
  sum_insured numeric(14,2) NOT NULL,
  employee_premium_monthly numeric(10,2) NOT NULL,
  employer_premium_monthly numeric(10,2) NOT NULL,
  coverage varchar(20) NOT NULL,
  eligibility text NOT NULL,
  active boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_insurance_plans_code UNIQUE (org_id, insurance_plan_code),
  CONSTRAINT ck_insurance_plans_kind CHECK (kind IN ('ESI', 'Group mediclaim', 'Group term life', 'Personal accident'))
);
-- IpRule — Network restriction for sign-in / punching.
CREATE TABLE ip_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ip_rule_code varchar(8) NOT NULL,
  name varchar(80) NOT NULL,
  address cidr NOT NULL,
  restricted boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_ip_rules_code UNIQUE (org_id, ip_rule_code)
);
-- LeavePolicy — Entity leave policy (clubbing, sandwich rule, EL encashment, comp-off validity).
CREATE TABLE leave_policies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  leave_policy_code bigint NOT NULL,
  org_id uuid NOT NULL,
  allow_club_s_l_c_l_with_holiday boolean NOT NULL,
  allow_club_s_l_c_l_with_e_l boolean NOT NULL,
  sandwich_rule boolean NOT NULL,
  el_encashment_month smallint NOT NULL,
  el_encash_max_days smallint NOT NULL,
  el_encash_basis varchar(6) NOT NULL,
  el_encash_component varchar(60) NOT NULL,
  comp_off_validity_days smallint NOT NULL,
  updated_by varchar(120) NOT NULL,
  updated_on date NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_leave_policies_code UNIQUE (org_id, leave_policy_code),
  CONSTRAINT ck_leave_policies_el_encash_basis CHECK (el_encash_basis IN ('Gross', 'Basic'))
);
-- LeaveType — Leave master with credit, carry-forward, encashment and approval rules.
CREATE TABLE leave_types (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  leave_type_code varchar(8) NOT NULL,
  name varchar(60) NOT NULL,
  code varchar(6) NOT NULL,
  annual numeric(5,1) NOT NULL,
  credit_frequency varchar(20) NOT NULL,
  carry_forward boolean NOT NULL,
  max_carry numeric(5,1) NOT NULL,
  encashable boolean NOT NULL,
  encash_on varchar(6) NOT NULL,
  clubbable boolean NOT NULL,
  min_days numeric(3,1) NOT NULL,
  max_consecutive smallint NOT NULL,
  needs_attachment boolean NOT NULL,
  attachment_after_days smallint NOT NULL,
  approval_chain varchar(24) NOT NULL,
  validity_days smallint NOT NULL,
  paid boolean NOT NULL,
  applicable_to varchar(60) NOT NULL,
  active boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_leave_types_code UNIQUE (org_id, leave_type_code),
  CONSTRAINT ck_leave_types_credit_frequency CHECK (credit_frequency IN ('Quarterly pro-rata', 'Monthly pro-rata', 'Annual upfront', 'On event')),
  CONSTRAINT ck_leave_types_encash_on CHECK (encash_on IN ('Gross', 'Basic')),
  CONSTRAINT ck_leave_types_approval_chain CHECK (approval_chain IN ('Manager', 'Manager → HR', 'HOD', 'HOD → HR', 'Manager → HOD → HR'))
);
-- MasterEntry — Generic master-data rows for CrudSection-based masters (job types, trainers, pay grades …) keyed by section.
CREATE TABLE master_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  section_key varchar(80) NOT NULL,
  data jsonb NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_master_entries_key UNIQUE (org_id, section_key, code)
);
-- MasterItem — Generic name/description masters: onboarding documents (DOC), awards (AWD), termination types (TTY), warning types (WTY), complaint types (CTY).
CREATE TABLE master_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  master_item_code varchar(10) NOT NULL,
  kind varchar(4) NOT NULL,
  name varchar(80) NOT NULL,
  description text,
  required boolean,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_master_items_code UNIQUE (org_id, master_item_code),
  CONSTRAINT ck_master_items_kind CHECK (kind IN ('DOC', 'AWD', 'TTY', 'WTY', 'CTY'))
);
-- PayComponent — Pay component rendered in the employee compensation form.
CREATE TABLE pay_components (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  pay_component_code varchar(8) NOT NULL,
  name varchar(80) NOT NULL,
  code varchar(12) NOT NULL,
  kind varchar(10) NOT NULL,
  calculation varchar(12) NOT NULL,
  value varchar(20) NOT NULL,
  description text,
  show_in_employee_form boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_pay_components_code UNIQUE (org_id, pay_component_code),
  CONSTRAINT ck_pay_components_kind CHECK (kind IN ('Allowance', 'Deduction', 'Earning', 'Statutory')),
  CONSTRAINT ck_pay_components_calculation CHECK (calculation IN ('Flat', '% of Basic', '% of CTC', 'Balancing', 'Annual'))
);
-- PolicyDocument — Seed policy/circular list used by /org/masters (Policies & Circulars).
CREATE TABLE policy_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  policy_document_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(200) NOT NULL,
  category varchar(30) NOT NULL,
  description text,
  file_name varchar(255) NOT NULL,
  updated_on date NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_policy_documents_code UNIQUE (org_id, policy_document_code),
  CONSTRAINT ck_policy_documents_category CHECK (category IN ('HR Policy', 'Compliance', 'Finance', 'IT & Security', 'Health & Safety'))
);

-- =============================================================================
-- Time, Attendance, Leave & Travel
-- =============================================================================

-- ApprovalStep — Generic approval-chain step shared by tours and comp-off (and assets / appraisals elsewhere).
CREATE TABLE approval_steps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subject_type varchar(30) NOT NULL,
  subject_id varchar(12) NOT NULL,
  seq smallint NOT NULL,
  role varchar(12) NOT NULL,
  label varchar(60) NOT NULL,
  approver_id uuid,
  approver_name varchar(120) NOT NULL,
  status varchar(10) NOT NULL,
  acted_on date,
  note text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_approval_steps_key UNIQUE (subject_type, subject_id, seq),
  CONSTRAINT ck_approval_steps_subject_type CHECK (subject_type IN ('tour', 'compoff_redemption')),
  CONSTRAINT ck_approval_steps_role CHECK (role IN ('HOD', 'Manager', 'HRPartner', 'HR', 'CFO', '…AppRole')),
  CONSTRAINT ck_approval_steps_status CHECK (status IN ('Pending', 'Approved', 'Rejected', 'Skipped'))
);
-- AttendanceLock — HR lock of a month's attendance for payroll, per entity.
CREATE TABLE attendance_locks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  period char(7) NOT NULL,
  locked_by varchar(120) NOT NULL,
  locked_on date NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_locks_key UNIQUE (org_id, period),
  CONSTRAINT ck_attendance_locks_period_fmt CHECK (period IS NULL OR period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$')
);
-- OvertimeRule — Overtime / comp-off reward rule (OTR-04 drives comp-off accrual).
CREATE TABLE attendance_overtime_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  applies_after varchar(80) NOT NULL,
  reward_type varchar(32) NOT NULL,
  reward_value varchar(40) NOT NULL,
  requires_approval boolean NOT NULL,
  monthly_cap varchar(40) NOT NULL,
  active boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_overtime_rules_key UNIQUE (org_id, code),
  CONSTRAINT ck_attendance_overtime_rules_reward_type CHECK (reward_type IN ('Multiplier of Hourly Rate', 'Fixed Amount / hr', 'Comp Off'))
);
-- AttendancePattern — Pay-as-you-go pattern: payable days and paid absences before LOP.
CREATE TABLE attendance_patterns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  working_days integer NOT NULL,
  paid_leave_days integer NOT NULL,
  lop_enabled boolean NOT NULL,
  weekly_offs integer NOT NULL,
  description text,
  status varchar(8) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_patterns_key UNIQUE (org_id, code),
  CONSTRAINT ck_attendance_patterns_status CHECK (status IN ('Active', 'Draft'))
);
-- PenaltyRule — Deduction rule for short hours / late / half day / absence / early exit.
CREATE TABLE attendance_penalty_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  trigger varchar(20) NOT NULL,
  threshold varchar(80) NOT NULL,
  deduction_type varchar(24) NOT NULL,
  deduction_value varchar(40) NOT NULL,
  grace_count integer NOT NULL,
  applies_to varchar(80) NOT NULL,
  active boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_penalty_rules_key UNIQUE (org_id, code),
  CONSTRAINT ck_attendance_penalty_rules_trigger CHECK (trigger IN ('Short Hours', 'Late Arrival', 'Half Day', 'Absent', 'Early Exit')),
  CONSTRAINT ck_attendance_penalty_rules_deduction_type CHECK (deduction_type IN ('Fixed Amount', '% of Daily Wage', 'Leave Deduction'))
);
-- Punch — A self-service clock-in / clock-out (manual, biometric device or geofenced).
CREATE TABLE attendance_punches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(24) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  work_date date NOT NULL,
  in_time time NOT NULL,
  out_time time,
  source varchar(12) NOT NULL,
  location varchar(160) NOT NULL,
  note text,
  geofence_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_punches_key UNIQUE (employee_id),
  CONSTRAINT ck_attendance_punches_source CHECK (source IN ('Manual', 'Biometric', 'Geofence'))
);
-- AttendanceDay — Daily P/A/L register (seed baseline + punches + approved leave / comp-off), read by the report, reviews and payroll.
CREATE TABLE attendance_register (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  org_id uuid NOT NULL,
  att_date date NOT NULL,
  status char(1) NOT NULL,
  source varchar(16),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_register_key UNIQUE (employee_id, att_date),
  CONSTRAINT ck_attendance_register_status CHECK (status IN ('P', 'A', 'L'))
);
-- WorkDayRecord — Per-day computed work hours (seed register + derived from punches) used for OT / short hours / late marks.
CREATE TABLE attendance_work_days (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  org_id uuid NOT NULL,
  work_date date NOT NULL,
  shift_name varchar(80) NOT NULL,
  check_in time,
  check_out time,
  worked_hours numeric(5,2) NOT NULL,
  required_hours numeric(5,2) NOT NULL,
  break_minutes integer NOT NULL,
  late_minutes integer NOT NULL,
  early_out_minutes integer NOT NULL,
  day_type varchar(12) NOT NULL,
  ot_approved boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_work_days_key UNIQUE (employee_id, work_date),
  CONSTRAINT ck_attendance_work_days_day_type CHECK (day_type IN ('Full Day', 'Half Day', 'Absent', 'Leave', 'Week Off'))
);
-- HalfDayPolicy — Full/half-day hour thresholds and windows (one row per entity).
CREATE TABLE attendance_work_hour_policy (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  min_hours_full_day numeric(4,2) NOT NULL,
  min_hours_half_day numeric(4,2) NOT NULL,
  first_half_window varchar(20) NOT NULL,
  second_half_window varchar(20) NOT NULL,
  max_half_days_per_month integer NOT NULL,
  counts_against_leave boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_attendance_work_hour_policy_key UNIQUE (org_id)
);
-- CompOffLedgerEntry — Comp-off credit (auto: worked / toured on an off day) or debit (approved redemption).
CREATE TABLE compoff_ledger (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  employee_id uuid NOT NULL,
  entry_type varchar(6) NOT NULL,
  days numeric(4,1) NOT NULL,
  reason text NOT NULL,
  source_kind varchar(16),
  source_date date,
  source_punch_id uuid,
  source_tour_id uuid,
  created_on date NOT NULL,
  expires_on date,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_compoff_ledger_key UNIQUE (source_kind, source_punch_id),
  CONSTRAINT ck_compoff_ledger_entry_type CHECK (entry_type IN ('Credit', 'Debit')),
  CONSTRAINT ck_compoff_ledger_source_kind CHECK (source_kind IN ('worked-off-day', 'tour-off-day'))
);
-- CompOffRedemption — Request to avail comp-off days, HOD approval (fallback Manager → HR).
CREATE TABLE compoff_redemptions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  compoff_redemption_code bigint NOT NULL,
  code varchar(10) NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  from_date date NOT NULL,
  to_date date NOT NULL,
  days numeric(4,1) NOT NULL,
  reason text NOT NULL,
  status varchar(20) NOT NULL,
  raised_on date NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_compoff_redemptions_code UNIQUE (org_id, compoff_redemption_code),
  CONSTRAINT ck_compoff_redemptions_status CHECK (status IN ('Pending Approval', 'Approved', 'Rejected')),
  CONSTRAINT ck_compoff_redemptions_to_date_after_from_date CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date)
);
-- EmployeeWorkConfig — Per-employee pattern + optional workday override (days/week, hours/day, week-offs, timesheet requirement).
CREATE TABLE employee_work_configs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  pattern_id uuid NOT NULL,
  days_per_week smallint,
  hours_per_day numeric(4,2),
  timesheet_required boolean,
  week_offs varchar(3)[],
  note text,
  updated_on date NOT NULL,
  updated_by varchar(120) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employee_work_configs_key UNIQUE (employee_id)
);
-- LeaveApplicationApprovals — Child of leave_applications — leave_application_approvals (flattened from chainLog[]: step, by, on, note)
CREATE TABLE leave_application_approvals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  leave_application_id uuid NOT NULL,
  step varchar(120),
  action_by varchar(120),
  action_on date,
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- LeaveApplicationDocuments — Child of leave_applications — leave_application_documents (from documents[])
CREATE TABLE leave_application_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  leave_application_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- LeaveApplication — Leave request with multi-step approval chain from the Leave Master.
CREATE TABLE leave_applications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  leave_application_code bigint NOT NULL,
  code varchar(12) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  leave_type_id uuid NOT NULL,
  from_date date NOT NULL,
  to_date date NOT NULL,
  days numeric(5,1) NOT NULL,
  day_part varchar(12),
  description text NOT NULL,
  reason_category varchar(40),
  attachment varchar(255),
  documents text,
  contact_during_leave varchar(120),
  location_during_leave varchar(120),
  handover_to varchar(120),
  handover_notes text,
  status varchar(10) NOT NULL,
  approval_chain varchar(60),
  chain_step smallint,
  decision_reason text,
  decided_by varchar(120),
  decided_on date,
  applied_on date,
  applied_by varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_leave_applications_code UNIQUE (org_id, leave_application_code),
  CONSTRAINT ck_leave_applications_day_part CHECK (day_part IN ('Full day', 'First half', 'Second half')),
  CONSTRAINT ck_leave_applications_status CHECK (status IN ('Pending', 'Approved', 'Rejected')),
  CONSTRAINT ck_leave_applications_to_date_after_from_date CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date)
);
-- Shift — Shift master (timings, break window, office).
CREATE TABLE shifts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(80) NOT NULL,
  start_time time NOT NULL,
  end_time time NOT NULL,
  break_enabled boolean NOT NULL,
  break_start time,
  break_end time,
  office varchar(80) NOT NULL,
  headcount integer NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_shifts_key UNIQUE (org_id)
);
-- TimesheetEntry — One task line on a day, submitted for manager approval.
CREATE TABLE timesheet_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  timesheet_entry_code bigint NOT NULL,
  code varchar(12) NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  format_name varchar(120) NOT NULL,
  work_date date NOT NULL,
  task varchar(200) NOT NULL,
  description text,
  start_time time,
  end_time time,
  hours numeric(5,2) NOT NULL,
  task_status varchar(16) NOT NULL,
  status varchar(10) NOT NULL,
  approver_remarks text,
  project varchar(120),
  billable boolean,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_timesheet_entries_code UNIQUE (org_id, timesheet_entry_code),
  CONSTRAINT ck_timesheet_entries_task_status CHECK (task_status IN ('Not Started', 'In Progress', 'Completed', 'Blocked')),
  CONSTRAINT ck_timesheet_entries_status CHECK (status IN ('Draft', 'Submitted', 'Approved', 'Rejected'))
);
-- TimesheetFormat — Timesheet template configured by HR (frequency + visible fields).
CREATE TABLE timesheet_formats (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  frequency varchar(8) NOT NULL,
  department varchar(80) NOT NULL,
  fields varchar(20)[] NOT NULL,
  description text,
  active boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_timesheet_formats_key UNIQUE (org_id, name),
  CONSTRAINT ck_timesheet_formats_frequency CHECK (frequency IN ('Daily', 'Weekly', 'Monthly'))
);
-- TourBill — Bill attached to a tour for audit; can be claimed as an expense line.
CREATE TABLE tour_bills (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tour_id uuid NOT NULL,
  code varchar(6) NOT NULL,
  name varchar(160) NOT NULL,
  vendor varchar(120) NOT NULL,
  invoice_no varchar(60),
  category varchar(24) NOT NULL,
  amount numeric(14,2) NOT NULL,
  gst numeric(14,2) NOT NULL,
  bill_date date NOT NULL,
  paid_by varchar(16) NOT NULL,
  file varchar(255) NOT NULL,
  uploaded_by varchar(120) NOT NULL,
  uploaded_on date NOT NULL,
  tour_expense_id uuid,
  note text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_tour_bills_key UNIQUE (tour_id, code),
  CONSTRAINT ck_tour_bills_amount_nonneg CHECK (amount IS NULL OR amount >= 0),
  CONSTRAINT ck_tour_bills_paid_by CHECK (paid_by IN ('Employee', 'Company card', 'Advance', 'Vendor invoice'))
);
-- TourExpense — Expense line booked against a tour; approved lines less advance = encashable.
CREATE TABLE tour_expenses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tour_id uuid NOT NULL,
  code varchar(6) NOT NULL,
  head varchar(24) NOT NULL,
  amount numeric(14,2) NOT NULL,
  expense_date date NOT NULL,
  receipt_file varchar(255),
  approved boolean NOT NULL,
  vendor varchar(120),
  invoice_no varchar(60),
  paid_by varchar(16),
  note text,
  added_by varchar(120),
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_tour_expenses_key UNIQUE (tour_id, code),
  CONSTRAINT ck_tour_expenses_head CHECK (head IN ('Travel', 'Lodging', 'Food', 'Local conveyance', 'Client entertainment', 'Other')),
  CONSTRAINT ck_tour_expenses_amount_nonneg CHECK (amount IS NULL OR amount >= 0),
  CONSTRAINT ck_tour_expenses_paid_by CHECK (paid_by IN ('Employee', 'Company card', 'Advance'))
);
-- TourProofDocuments — Child of tours — tour_proof_documents (proofDocuments[]: name, url)
CREATE TABLE tour_proof_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tour_id uuid NOT NULL,
  name varchar(120),
  url varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- TourTravellers — Child of tours — tour_travellers (travellers[]: employee_id)
CREATE TABLE tour_travellers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tour_id uuid NOT NULL,
  employee_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- TourRequest — Business tour: request → HOD → HR → Finance approval (or HR-assigned, pre-approved), outcome, expenses, bills, petty-cash encashment.
CREATE TABLE tours (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tour_code bigint NOT NULL,
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  purpose text NOT NULL,
  destination varchar(160) NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  travel_mode varchar(16) NOT NULL,
  estimated_cost numeric(14,2) NOT NULL,
  cost_centre varchar(20) NOT NULL,
  status varchar(20) NOT NULL,
  raised_on date NOT NULL,
  outcome text,
  outcome_submitted_on date,
  advance_paid numeric(14,2),
  encashed_amount numeric(14,2),
  encashment_claim_id uuid,
  encashed_on date,
  assigned_by varchar(120),
  assigned_on date,
  assignment_note text,
  client varchar(120),
  project varchar(120),
  itinerary text,
  accommodation varchar(160),
  booking_refs varchar(200),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_tours_code UNIQUE (org_id, tour_code),
  CONSTRAINT ck_tours_travel_mode CHECK (travel_mode IN ('Road', 'Rail', 'Air', 'Own Vehicle', 'Site Transport')),
  CONSTRAINT ck_tours_estimated_cost_nonneg CHECK (estimated_cost IS NULL OR estimated_cost >= 0),
  CONSTRAINT ck_tours_status CHECK (status IN ('Draft', 'Pending Approval', 'Approved', 'Rejected', 'Completed', 'Closed')),
  CONSTRAINT ck_tours_advance_paid_nonneg CHECK (advance_paid IS NULL OR advance_paid >= 0),
  CONSTRAINT ck_tours_encashed_amount_nonneg CHECK (encashed_amount IS NULL OR encashed_amount >= 0),
  CONSTRAINT ck_tours_end_date_after_start_date CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);
-- WageAttendance — Daily muster mark for a wage worker.
CREATE TABLE wage_attendance (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  worker_id uuid NOT NULL,
  att_date date NOT NULL,
  mark varchar(2) NOT NULL,
  in_time time,
  out_time time,
  ot_hours numeric(4,1) NOT NULL,
  marked_by varchar(120) NOT NULL,
  note text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_wage_attendance_key UNIQUE (worker_id, att_date),
  CONSTRAINT ck_wage_attendance_mark CHECK (mark IN ('P', 'A', 'H', 'WO', 'PH'))
);
-- WageWorker — Daily / monthly wage worker (contract labour) — attendance only.
CREATE TABLE wage_workers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  wage_worker_code bigint NOT NULL,
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  wage_type varchar(14) NOT NULL,
  trade varchar(40) NOT NULL,
  contractor varchar(120) NOT NULL,
  work_order_id uuid,
  site varchar(160) NOT NULL,
  shift_id uuid NOT NULL,
  phone varchar(20),
  id_proof_masked varchar(40),
  joined_on date NOT NULL,
  status varchar(8) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_wage_workers_code UNIQUE (org_id, wage_worker_code),
  CONSTRAINT ck_wage_workers_wage_type CHECK (wage_type IN ('Daily wage', 'Monthly wage')),
  CONSTRAINT ck_wage_workers_status CHECK (status IN ('Active', 'Inactive'))
);
-- WorkOrderAssignment — Employee deployed on a work order (one active per employee).
CREATE TABLE work_order_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  work_order_id uuid NOT NULL,
  assigned_on date NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_work_order_assignments_key UNIQUE (employee_id)
);
-- WorkOrderAttachments — Child of work_orders — work_order_attachments (attachments[])
CREATE TABLE work_order_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  work_order_id uuid NOT NULL,
  attachments varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- WorkOrderLocations — Child of work_orders — work_order_locations (locations[])
CREATE TABLE work_order_locations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  work_order_id uuid NOT NULL,
  locations varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- WorkOrderShifts — Child of work_orders — work_order_shifts (shifts[]: shift_id, headcount, days)
CREATE TABLE work_order_shifts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  work_order_id uuid NOT NULL,
  shift_id uuid,
  headcount varchar(120),
  days varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- WorkOrder — Client engagement / site with shift plan, billing and approvals; drives assigned employees' shift.
CREATE TABLE work_orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  work_order_code bigint NOT NULL,
  code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(160) NOT NULL,
  client_site varchar(160) NOT NULL,
  home_office varchar(80) NOT NULL,
  primary_shift_id uuid NOT NULL,
  start_date date NOT NULL,
  end_date date,
  status varchar(10) NOT NULL,
  purpose varchar(60),
  details text,
  headcount integer,
  priority varchar(10),
  client_contact varchar(160),
  notes text,
  created_by varchar(120),
  created_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_work_orders_code UNIQUE (org_id, work_order_code),
  CONSTRAINT ck_work_orders_status CHECK (status IN ('Active', 'On Hold', 'Completed')),
  CONSTRAINT ck_work_orders_priority CHECK (priority IN ('Low', 'Normal', 'High', 'Critical')),
  CONSTRAINT ck_work_orders_end_date_after_start_date CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);

-- =============================================================================
-- Payroll, Statutory, Tax & Finance
-- =============================================================================

-- AnnualComplianceCalendar — Child of compliance_library — annual_compliance_calendar
CREATE TABLE annual_compliance_calendar (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  compliance_library_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- BranchStates — Child of state_statutory_policies — branch_states (branch → state)
CREATE TABLE branch_states (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  state_statutory_policy_id uuid NOT NULL,
  branch varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ClaimAttachments — Child of reimbursement_claims — claim_attachments
CREATE TABLE claim_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reimbursement_claim_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ClaimLineItems — Child of reimbursement_claims — claim_line_items (date, vendor, bill_no, description, amount, attachment, paid_via)
CREATE TABLE claim_line_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reimbursement_claim_id uuid NOT NULL,
  date date,
  vendor varchar(120),
  bill_no varchar(120),
  description text,
  amount numeric(14,2),
  attachment varchar(120),
  paid_via varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_claim_line_items_amount_nonneg CHECK (amount IS NULL OR amount >= 0)
);
-- ClaimTrail — Child of reimbursement_claims — claim_trail (stage, actor, action Submitted|Approved|Rejected|Processed, at, remarks)
CREATE TABLE claim_trail (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reimbursement_claim_id uuid NOT NULL,
  stage varchar(120),
  actor varchar(120),
  action text,
  action_at date,
  remarks text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_claim_trail_action CHECK (action IN ('Submitted', 'Approved', 'Rejected', 'Processed'))
);
-- ComplianceEntry — Static library of acts/codes with rates, due dates, forms, registers, penalties and config alignment check.
CREATE TABLE compliance_library (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  act text NOT NULL,
  short_name varchar(120) NOT NULL,
  category varchar(40) NOT NULL,
  authority varchar(120) NOT NULL,
  rates jsonb NOT NULL,
  due_dates jsonb NOT NULL,
  forms text[] NOT NULL,
  registers text[] NOT NULL,
  penalties text NOT NULL,
  latest_update jsonb NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_compliance_library_code UNIQUE (code)
);
-- ContributionDeclaration — Employee VPF / corporate NPS election for a FY; only Approved/Locked flow into payroll.
CREATE TABLE contribution_declarations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  fy varchar(12) NOT NULL,
  vpf jsonb NOT NULL,
  nps jsonb NOT NULL,
  status varchar(10) NOT NULL,
  updated_on date NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_contribution_declarations_key UNIQUE (employee_id, fy),
  CONSTRAINT ck_contribution_declarations_fy_fmt CHECK (fy IS NULL OR fy ~ '^[0-9]{4}-[0-9]{2}$'),
  CONSTRAINT ck_contribution_declarations_status CHECK (status IN ('Draft', 'Submitted', 'Approved', 'Locked'))
);
-- ContributionHistory — Child of contribution_declarations — contribution_history
CREATE TABLE contribution_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  contribution_declaration_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- InsuranceAssignment — Insurance policy assigned to an employee; employee share deducted monthly in payroll.
CREATE TABLE employee_insurance (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_insurance_code varchar(20) NOT NULL,
  employee_id uuid NOT NULL,
  insurer varchar(60) NOT NULL,
  policy_number varchar(40) NOT NULL,
  tpa varchar(60) NOT NULL,
  master_entry_id uuid NOT NULL,
  category uuid NOT NULL,
  sum_insured numeric(14,2) NOT NULL,
  annual_premium numeric(14,2) NOT NULL,
  monthly_deduction numeric(14,2) NOT NULL,
  valid_from date NOT NULL,
  valid_to date NOT NULL,
  nominee varchar(120) NOT NULL,
  dependents text NOT NULL,
  documents text[] NOT NULL,
  status varchar(8) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employee_insurance_code UNIQUE (org_id, employee_insurance_code),
  CONSTRAINT ck_employee_insurance_annual_premium_nonneg CHECK (annual_premium IS NULL OR annual_premium >= 0),
  CONSTRAINT ck_employee_insurance_monthly_deduction_nonneg CHECK (monthly_deduction IS NULL OR monthly_deduction >= 0),
  CONSTRAINT ck_employee_insurance_status CHECK (status IN ('Active', 'Lapsed')),
  CONSTRAINT ck_employee_insurance_valid_to_after_valid_from CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);
-- EmployeeStatutoryProfile — Per-employee PF/ESI applicability flags.
CREATE TABLE employee_statutory_profiles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  tax_regime varchar(12) NOT NULL,
  pf_applicable boolean NOT NULL,
  pf_international_worker boolean NOT NULL,
  pf_mode varchar(12),
  insurance_plan_ids text[],
  esi_override varchar(12) NOT NULL,
  is_pwd boolean NOT NULL,
  pan_verified boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_employee_statutory_profiles_key UNIQUE (employee_id),
  CONSTRAINT ck_employee_statutory_profiles_pf_mode CHECK (pf_mode IN ('Org default', 'Capped', 'Full')),
  CONSTRAINT ck_employee_statutory_profiles_esi_override CHECK (esi_override IN ('Auto', 'Covered', 'Not covered'))
);
-- ExpenditureAssetDetails — Child of expenditures — expenditure_asset_details (asset_name, quantity, unit_cost, tag, capitalise, useful_life_years, location, custodian)
CREATE TABLE expenditure_asset_details (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  expenditure_id uuid NOT NULL,
  asset_name varchar(120),
  quantity varchar(120),
  unit_cost numeric(14,2),
  tag varchar(120),
  capitalise boolean,
  useful_life_years varchar(120),
  location varchar(120),
  custodian varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_expenditure_asset_details_unit_cost_nonneg CHECK (unit_cost IS NULL OR unit_cost >= 0)
);
-- ExpenditureAttachments — Child of expenditures — expenditure_attachments
CREATE TABLE expenditure_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  expenditure_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
