-- Expenditure — General company spend booking (distinct from claims) with approval, payment and outcome.
CREATE TABLE expenditures (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  expenditure_code varchar(12) NOT NULL,
  org_id uuid NOT NULL,
  title varchar(160) NOT NULL,
  category varchar(40) NOT NULL,
  subcategory varchar(60) NOT NULL,
  purpose text NOT NULL,
  reason text NOT NULL,
  department varchar(80) NOT NULL,
  branch varchar(80) NOT NULL,
  requested_by_id uuid NOT NULL,
  concerned_person_id uuid NOT NULL,
  approved_by_id uuid,
  user_id uuid NOT NULL,
  spend_date date NOT NULL,
  spend_time time NOT NULL,
  cost_centre varchar(30) NOT NULL,
  budget_line varchar(80),
  priority varchar(20) NOT NULL,
  is_recurring boolean NOT NULL,
  vendor varchar(120) NOT NULL,
  vendor_gstin char(15),
  invoice_no varchar(40),
  payment_mode varchar(30) NOT NULL,
  payment_ref varchar(60),
  taxable_amount numeric(14,2) NOT NULL,
  gst_pct numeric(5,2) NOT NULL,
  gst_amount numeric(14,2) NOT NULL,
  total numeric(14,2) NOT NULL,
  status varchar(10) NOT NULL,
  description text,
  outcome text,
  outcome_submitted_on date,
  created_on date NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_expenditures_code UNIQUE (org_id, expenditure_code),
  CONSTRAINT ck_expenditures_taxable_amount_nonneg CHECK (taxable_amount IS NULL OR taxable_amount >= 0),
  CONSTRAINT ck_expenditures_gst_pct_pct CHECK (gst_pct IS NULL OR (gst_pct >= 0 AND gst_pct <= 100)),
  CONSTRAINT ck_expenditures_gst_amount_nonneg CHECK (gst_amount IS NULL OR gst_amount >= 0),
  CONSTRAINT ck_expenditures_total_nonneg CHECK (total IS NULL OR total >= 0),
  CONSTRAINT ck_expenditures_status CHECK (status IN ('Booked', 'Approved', 'Paid', 'Rejected'))
);
-- FilingEcrLines — Child of statutory_filings — filing_ecr_lines (uan, member_name, gross, epf/eps/edli wages, epf/eps/diff contributions, ncp_days, refund)
