  CONSTRAINT ck_loan_schedule_emi_nonneg CHECK (emi IS NULL OR emi >= 0),
  CONSTRAINT ck_loan_schedule_balance_nonneg CHECK (balance IS NULL OR balance >= 0),
  CONSTRAINT ck_loan_schedule_via CHECK (via IN ('Payroll', 'F&F', 'Cash'))
);
