  tenure_months smallint NOT NULL,
  emi numeric(14,2) NOT NULL,
  interest_pct numeric(5,2) NOT NULL,
  purpose text NOT NULL,
  applied_on date NOT NULL,
  status varchar(10) NOT NULL,
  approved_by varchar(120),
  disbursed_on date,
  first_emi_period char(7) NOT NULL,
  fnf_recovered numeric(14,2),
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_loans_code UNIQUE (org_id, loan_code),
  CONSTRAINT ck_loans_kind CHECK (kind IN ('Salary advance', 'Loan')),
  CONSTRAINT ck_loans_amount_nonneg CHECK (amount IS NULL OR amount >= 0),
  CONSTRAINT ck_loans_emi_nonneg CHECK (emi IS NULL OR emi >= 0),
  CONSTRAINT ck_loans_interest_pct_pct CHECK (interest_pct IS NULL OR (interest_pct >= 0 AND interest_pct <= 100)),
  CONSTRAINT ck_loans_status CHECK (status IN ('Applied', 'Approved', 'Disbursed', 'Closing', 'Closed', 'Rejected'))
);
-- PayGrade — Pay grade bands (Masters).
CREATE TABLE pay_grades (
