  CONSTRAINT ck_pay_grades_min_ctc_nonneg CHECK (min_ctc IS NULL OR min_ctc >= 0),
  CONSTRAINT ck_pay_grades_max_ctc_nonneg CHECK (max_ctc IS NULL OR max_ctc >= 0)
);
-- PayrollLineDeductions — Child of payroll_run_lines — payroll_line_deductions
CREATE TABLE payroll_line_deductions (
