-- PayrollPolicy — Processing day / evaluation checkpoint / attendance cut-off.
CREATE TABLE payroll_policies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payroll_policy_code bigint NOT NULL,
  org_id uuid NOT NULL,
  processing_day varchar(20) NOT NULL,
  fixed_day smallint NOT NULL,
  evaluation_lead_days smallint NOT NULL,
  evaluator_role varchar(6) NOT NULL,
  cutoff_day smallint NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_payroll_policies_code UNIQUE (org_id, payroll_policy_code),
  CONSTRAINT ck_payroll_policies_processing_day CHECK (processing_day IN ('Last day of month', 'Last working day', 'Fixed day')),
  CONSTRAINT ck_payroll_policies_evaluator_role CHECK (evaluator_role IN ('HR', 'CHRO', 'CFO'))
);
-- PayrollApproval — Decision at one approval level of a run.
CREATE TABLE payroll_run_approvals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payroll_run_approval_code bigint NOT NULL,
  run_id uuid NOT NULL,
  level varchar(30) NOT NULL,
