  approver_name varchar(120) NOT NULL,
  decided_on date NOT NULL,
  decision varchar(10) NOT NULL,
  remarks text NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_payroll_run_approvals_code UNIQUE (org_id, payroll_run_approval_code),
  CONSTRAINT ck_payroll_run_approvals_level CHECK (level IN ('Payroll Admin', 'HR Manager', 'Finance', 'CFO')),
  CONSTRAINT ck_payroll_run_approvals_decision CHECK (decision IN ('Approved', 'Rejected'))
);
-- ComplianceCheck — Pre-approval compliance check raised on a run; resolvable by record fix, override (with justification) or escalation.
CREATE TABLE payroll_run_checks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  check_key varchar(60) NOT NULL,
  run_id uuid NOT NULL,
  code varchar(20) NOT NULL,
  level varchar(10) NOT NULL,
  employee_id uuid,
  employee_name varchar(120),
  message text NOT NULL,
  acknowledged boolean,
  status varchar(12) NOT NULL,
  resolution jsonb,
  escalation jsonb,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_payroll_run_checks_key UNIQUE (run_id, check_key),
  CONSTRAINT ck_payroll_run_checks_code CHECK (code IN ('ATT-LOCK', 'NET-NEG', 'LOP-GT-WD', 'PF-UAN', 'PF-NO', 'ESI-IP', 'ESI-EXCL', 'ESI-LOCK', 'TDS-PAN', 'MIN-WAGE', 'NCP-DIM', 'ATT-SRC', 'VPF-CAP', 'PT-STATE')),
  CONSTRAINT ck_payroll_run_checks_level CHECK (level IN ('error', 'warning', 'info')),
  CONSTRAINT ck_payroll_run_checks_status CHECK (status IN ('Open', 'Resolved', 'Overridden', 'Escalated'))
);
-- PayrollRunHistory — Child of payroll_runs — payroll_run_history (history[])
CREATE TABLE payroll_run_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payroll_run_id uuid NOT NULL,
  history varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- PayrollRunLine — One employee's computed payslip inside a run (attendance → LOP → earnings → PF/ESI/PT/LWF/NPS/TDS/loan → net).
CREATE TABLE payroll_run_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  designation varchar(80) NOT NULL,
  branch varchar(80) NOT NULL,
  state varchar(30) NOT NULL,
  is_wage_roll boolean NOT NULL,
  structure_gross numeric(14,2) NOT NULL,
  earned_gross numeric(14,2) NOT NULL,
  lop jsonb NOT NULL,
  earnings jsonb NOT NULL,
  deductions jsonb NOT NULL,
  pf_wages numeric(14,2) NOT NULL,
  eps_wages numeric(14,2) NOT NULL,
  pf_employee numeric(14,2) NOT NULL,
  vpf numeric(14,2) NOT NULL,
  pf_employer_epf numeric(14,2) NOT NULL,
  pf_employer_eps numeric(14,2) NOT NULL,
  edli numeric(14,2) NOT NULL,
  pf_admin numeric(14,2) NOT NULL,
  ncp_days smallint NOT NULL,
  esi_applicable boolean NOT NULL,
  esi_wages numeric(14,2) NOT NULL,
  esi_employee numeric(14,2) NOT NULL,
  esi_employer numeric(14,2) NOT NULL,
  professional_tax numeric(14,2) NOT NULL,
  lwf_employee numeric(14,2) NOT NULL,
  lwf_employer numeric(14,2) NOT NULL,
  nps_employee numeric(14,2) NOT NULL,
  nps_employer numeric(14,2) NOT NULL,
  pran varchar(12),
  tds_working jsonb NOT NULL,
  tds_monthly numeric(14,2) NOT NULL,
  loan_emi numeric(14,2) NOT NULL,
  total_deductions numeric(14,2) NOT NULL,
  net_pay numeric(14,2) NOT NULL,
  employer_cost numeric(14,2) NOT NULL,
  statutory_ids jsonb NOT NULL,
  bank jsonb NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_payroll_run_lines_key UNIQUE (run_id, employee_id),
  CONSTRAINT ck_payroll_run_lines_structure_gross_nonneg CHECK (structure_gross IS NULL OR structure_gross >= 0),
  CONSTRAINT ck_payroll_run_lines_earned_gross_nonneg CHECK (earned_gross IS NULL OR earned_gross >= 0),
  CONSTRAINT ck_payroll_run_lines_professional_tax_nonneg CHECK (professional_tax IS NULL OR professional_tax >= 0),
  CONSTRAINT ck_payroll_run_lines_loan_emi_nonneg CHECK (loan_emi IS NULL OR loan_emi >= 0),
  CONSTRAINT ck_payroll_run_lines_employer_cost_nonneg CHECK (employer_cost IS NULL OR employer_cost >= 0)
);
-- PayrollRun — Monthly (or other frequency) payroll run with maker–checker workflow; holds the computed register at the time of the last check.
CREATE TABLE payroll_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payroll_run_code varchar(30) NOT NULL,
  org_id uuid NOT NULL,
  title varchar(120) NOT NULL,
  period char(7) NOT NULL,
  frequency varchar(20) NOT NULL,
  pay_date date NOT NULL,
  bank_account varchar(80) NOT NULL,
  status varchar(20) NOT NULL,
  prepared_by_id uuid NOT NULL,
  prepared_by_name varchar(120) NOT NULL,
  prepared_on date NOT NULL,
  checked_on timestamptz,
  approval_levels text[] NOT NULL,
  processed_on date,
  processed_by varchar(120),
  paid_on date,
  payment_ref varchar(60),
  totals jsonb NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_payroll_runs_code UNIQUE (org_id, payroll_run_code),
  CONSTRAINT ck_payroll_runs_period_fmt CHECK (period IS NULL OR period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT ck_payroll_runs_frequency CHECK (frequency IN ('Monthly', 'Bi-weekly', 'Weekly', 'Quarterly')),
  CONSTRAINT ck_payroll_runs_status CHECK (status IN ('Draft', 'Checks Failed', 'Checks Passed', 'Pending Approval', 'Approved', 'Rejected', 'Processed', 'Paid'))
);
-- PayslipConfig — Payslip branding and printed fields.
CREATE TABLE payslip_configs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payslip_config_code bigint NOT NULL,
  org_id uuid NOT NULL,
  title varchar(60) NOT NULL,
  brand_name varchar(120) NOT NULL,
  brand_logo varchar(160) NOT NULL,
  fields jsonb NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_payslip_configs_code UNIQUE (org_id, payslip_config_code)
);
-- PtSlabs — Child of state_statutory_policies — pt_slabs (state, up_to numeric null = and above, amount, note)
CREATE TABLE pt_slabs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  state_statutory_policy_id uuid NOT NULL,
  state varchar(120),
  up_to numeric(14,2),
  amount numeric(14,2),
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_pt_slabs_amount_nonneg CHECK (amount IS NULL OR amount >= 0)
);
-- ReimbursementCategory — Named masters: reimbursement categories, insurance types, insurance categories.
CREATE TABLE reimbursement_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reimbursement_category_code varchar(20) NOT NULL,
  name varchar(60) NOT NULL,
  description text NOT NULL,
  status varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_reimbursement_categories_code UNIQUE (org_id, reimbursement_category_code)
);
-- ReimbursementClaim — Employee expense claim through Manager → HR → CHRO → CEO → CFO → Accounts.
CREATE TABLE reimbursement_claims (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  reimbursement_claim_code varchar(20) NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  title varchar(160) NOT NULL,
  type varchar(30) NOT NULL,
  reimbursement_category_id uuid NOT NULL,
  amount numeric(14,2) NOT NULL,
  expense_date date NOT NULL,
  document varchar(160),
  description text,
  status varchar(10) NOT NULL,
  remarks text,
  current_stage varchar(10) NOT NULL,
  stage_status varchar(10) NOT NULL,
  purpose text NOT NULL,
  project varchar(120),
  client varchar(120),
  cost_centre varchar(30),
  period_from date NOT NULL,
  period_to date NOT NULL,
  payment_mode varchar(30) NOT NULL,
  advance_adjusted numeric(14,2),
  advance_ref varchar(30),
  policy_limit numeric(14,2),
  submitted_on timestamptz NOT NULL,
  department varchar(80),
  designation varchar(80),
  branch varchar(80),
  bank_account varchar(60),
  declaration_accepted boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_reimbursement_claims_code UNIQUE (org_id, reimbursement_claim_code),
  CONSTRAINT ck_reimbursement_claims_type CHECK (type IN ('Expense Claim', 'Advance Settlement', 'Insurance Claim', 'Petty Cash')),
  CONSTRAINT ck_reimbursement_claims_amount_nonneg CHECK (amount IS NULL OR amount >= 0),
  CONSTRAINT ck_reimbursement_claims_status CHECK (status IN ('Submitted', 'Approved', 'Rejected', 'Paid')),
  CONSTRAINT ck_reimbursement_claims_current_stage CHECK (current_stage IN ('Manager', 'HR', 'CHRO', 'CEO', 'CFO', 'Accounts', 'Settled')),
  CONSTRAINT ck_reimbursement_claims_stage_status CHECK (stage_status IN ('Pending', 'Approved', 'Rejected', 'Processed')),
  CONSTRAINT ck_reimbursement_claims_payment_mode CHECK (payment_mode IN ('With salary (payroll)', 'Bank transfer', 'Petty cash')),
  CONSTRAINT ck_reimbursement_claims_policy_limit_nonneg CHECK (policy_limit IS NULL OR policy_limit >= 0),
  CONSTRAINT ck_reimbursement_claims_period_to_after_period_from CHECK (period_to IS NULL OR period_from IS NULL OR period_to >= period_from)
);
-- SalaryComponents — Child of salary_structures — salary_components (code, label, section Inclusion|Exclusion, basis % of CTC|% of Basic|Fixed monthly|Balancing, value, cap, taxable
CREATE TABLE salary_components (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  salary_structure_id uuid NOT NULL,
  code varchar(120),
  label varchar(120),
  section varchar(120),
  basis varchar(120),
  value varchar(120),
  cap varchar(120),
  taxable numeric(14,2),
  statutory varchar(120),
  show_on_payslip varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_salary_components_section CHECK (section IN ('Inclusion', 'Exclusion')),
  CONSTRAINT ck_salary_components_basis CHECK (basis IN ('Basic', 'Fixed monthly', 'Balancing'))
);
-- SalaryStructure — Grade-wise salary structure (inclusions/exclusions) used to break a CTC into components.
CREATE TABLE salary_structures (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grade varchar(10) NOT NULL,
  name varchar(120) NOT NULL,
  wage_type varchar(14) NOT NULL,
  working_days smallint NOT NULL,
  notes text NOT NULL,
  active boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_salary_structures_code UNIQUE (org_id, grade),
  CONSTRAINT ck_salary_structures_wage_type CHECK (wage_type IN ('Salaried', 'Monthly wage', 'Daily wage'))
);
-- StatePolicy — Per-state Professional Tax slabs, LWF cycle, minimum wage and ESI zone (reference data).
CREATE TABLE state_statutory_policies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  state varchar(30) NOT NULL,
  pt_applicable boolean NOT NULL,
  pt_half_yearly boolean,
  pt_adjust_month jsonb,
  lwf jsonb NOT NULL,
  minimum_wage numeric(14,2) NOT NULL,
  esi_zone varchar(30) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_state_statutory_policies_code UNIQUE (state),
  CONSTRAINT ck_state_statutory_policies_minimum_wage_nonneg CHECK (minimum_wage IS NULL OR minimum_wage >= 0)
);
-- StatutoryConfig — Organisation statutory policy: establishment registrations, PF, ESI, TDS (new regime only) and payroll approval policy.
CREATE TABLE statutory_configs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  pf_establishment_code varchar(20) NOT NULL,
  esi_employer_code varchar(17) NOT NULL,
  tan char(10) NOT NULL,
  pan char(10) NOT NULL,
  registered_state varchar(30) NOT NULL,
  ptrc_number varchar(40) NOT NULL,
  pf_enabled boolean NOT NULL,
  pf_employee_rate numeric(5,2) NOT NULL,
  pf_employer_rate numeric(5,2) NOT NULL,
  eps_rate numeric(5,2) NOT NULL,
  edli_rate numeric(5,2) NOT NULL,
  pf_admin_rate numeric(5,2) NOT NULL,
  pf_wage_ceiling numeric(14,2) NOT NULL,
  pf_restrict_to_ceiling boolean NOT NULL,
  pf_employer_on_actual boolean NOT NULL,
  pf_due_day smallint NOT NULL,
  esi_enabled boolean NOT NULL,
  esi_employee_rate numeric(5,2) NOT NULL,
  esi_employer_rate numeric(5,2) NOT NULL,
  esi_wage_threshold numeric(14,2) NOT NULL,
  esi_pwd_threshold numeric(14,2) NOT NULL,
  esi_due_day smallint NOT NULL,
  esi_lock_membership boolean NOT NULL,
  tax_regime varchar(12) NOT NULL,
  standard_deduction numeric(14,2) NOT NULL,
  cess_rate numeric(5,2) NOT NULL,
  rebate_87a_limit numeric(14,2) NOT NULL,
  rebate_87a_max numeric(14,2) NOT NULL,
  tds_due_day smallint NOT NULL,
  nps_80ccd2_cap_pct numeric(5,2) NOT NULL,
  approval_levels text[] NOT NULL,
  enforce_maker_checker boolean NOT NULL,
  block_on_errors boolean NOT NULL,
  require_attendance_lock boolean NOT NULL,
  pay_day smallint NOT NULL,
  updated_on date NOT NULL,
  updated_by varchar(120) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_statutory_configs_key UNIQUE (org_id),
  CONSTRAINT ck_statutory_configs_tan_fmt CHECK (tan IS NULL OR tan ~ '^[A-Z]{4}[0-9]{5}[A-Z]$'),
  CONSTRAINT ck_statutory_configs_pan_fmt CHECK (pan IS NULL OR pan ~ '^[A-Z]{5}[0-9]{4}[A-Z]$'),
  CONSTRAINT ck_statutory_configs_standard_deduction_nonneg CHECK (standard_deduction IS NULL OR standard_deduction >= 0),
  CONSTRAINT ck_statutory_configs_rebate_87a_limit_nonneg CHECK (rebate_87a_limit IS NULL OR rebate_87a_limit >= 0),
  CONSTRAINT ck_statutory_configs_nps_80ccd2_cap_pct_pct CHECK (nps_80ccd2_cap_pct IS NULL OR (nps_80ccd2_cap_pct >= 0 AND nps_80ccd2_cap_pct <= 100))
);
-- StatutoryFiling — ECR / ESI / TDS filing generated from a processed run, with verify → approve → file → pay workflow.
CREATE TABLE statutory_filings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  statutory_filing_code varchar(30) NOT NULL,
  kind varchar(4) NOT NULL,
  org_id uuid NOT NULL,
  run_id uuid NOT NULL,
  period char(7) NOT NULL,
  status varchar(10) NOT NULL,
  due_on date NOT NULL,
  member_count integer NOT NULL,
  total_amount numeric(14,2) NOT NULL,
  ecr_accounts jsonb,
  validation jsonb NOT NULL,
  file_name varchar(120) NOT NULL,
  generated_by_id uuid NOT NULL,
  generated_on date NOT NULL,
  verified_by varchar(120),
  approved_by varchar(120),
  reference_no varchar(60),
  filed_on date,
  paid_on date,
  payment_ref varchar(60),
  is_supplementary boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_statutory_filings_code UNIQUE (org_id, statutory_filing_code),
  CONSTRAINT ck_statutory_filings_kind CHECK (kind IN ('ECR', 'ESI', 'TDS')),
  CONSTRAINT ck_statutory_filings_period_fmt CHECK (period IS NULL OR period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT ck_statutory_filings_status CHECK (status IN ('Draft', 'Verified', 'Approved', 'Filed', 'Paid')),
  CONSTRAINT ck_statutory_filings_total_amount_nonneg CHECK (total_amount IS NULL OR total_amount >= 0)
);
-- SurchargeTiers — Child of income_tax_slabs — surcharge_tiers (fy, above, rate)
CREATE TABLE surcharge_tiers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  income_tax_slab_id uuid NOT NULL,
  fy varchar(120),
  above varchar(120),
  rate varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_surcharge_tiers_fy_fmt CHECK (fy IS NULL OR fy ~ '^[0-9]{4}-[0-9]{2}$')
);
-- TaxDocumentHistory — Child of tax_documents — tax_document_history
CREATE TABLE tax_document_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tax_document_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- TaxDocumentQuarters — Child of tax_documents — tax_document_quarters (from working.quarters)
CREATE TABLE tax_document_quarters (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tax_document_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- TaxDocument — Form 16 / 12BA / 12BB records — generated from payroll (with full Part A/B working) or uploaded.
CREATE TABLE tax_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tax_document_code varchar(20) NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  form varchar(24) NOT NULL,
  fy varchar(12) NOT NULL,
  quarter varchar(10) NOT NULL,
  file_name varchar(160) NOT NULL,
  gross_salary_text varchar(40) NOT NULL,
  tax_deducted_text varchar(40) NOT NULL,
  status varchar(10) NOT NULL,
  issued_on date NOT NULL,
  source varchar(10) NOT NULL,
  form16_working jsonb,
  uploaded_note text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_tax_documents_code UNIQUE (org_id, tax_document_code),
  CONSTRAINT ck_tax_documents_form CHECK (form IN ('Form 16', 'Form 12BB', 'Form 12BA', 'Form 16 Part A only')),
  CONSTRAINT ck_tax_documents_fy_fmt CHECK (fy IS NULL OR fy ~ '^[0-9]{4}-[0-9]{2}$'),
  CONSTRAINT ck_tax_documents_status CHECK (status IN ('Generated', 'Uploaded', 'Pending', 'Verified', 'Issued')),
  CONSTRAINT ck_tax_documents_source CHECK (source IN ('Generated', 'Uploaded'))
);
-- WageRollEmployee — Muster-only staff paid by payroll but not in the HR directory (drivers, helpers, security).
CREATE TABLE wage_roll_employees (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  wage_roll_employee_code varchar(30) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  designation varchar(80) NOT NULL,
  branch varchar(80) NOT NULL,
  gender varchar(10) NOT NULL,
  dob date NOT NULL,
  doj date NOT NULL,
  ctc numeric(14,2) NOT NULL,
  earnings jsonb NOT NULL,
  statutory_ids jsonb NOT NULL,
  bank jsonb NOT NULL,
  status varchar(12) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_wage_roll_employees_code UNIQUE (org_id, wage_roll_employee_code),
  CONSTRAINT ck_wage_roll_employees_ctc_nonneg CHECK (ctc IS NULL OR ctc >= 0)
);

-- =============================================================================
-- Performance, Goals & Learning
-- =============================================================================

-- AppraisalCycleStages — Child of appraisal_cycles — appraisal_cycle_stages (self/hod/hr StageRecord: stage enum, rating varchar(20) '1 — Below'…'5 — Outstanding', comments, submitted_b
CREATE TABLE appraisal_cycle_stages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  appraisal_cycle_id uuid NOT NULL,
  self varchar(120),
  rating varchar(20),
  comments varchar(120),
  user_id uuid,
  submitted_on varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- AppraisalCycle — Staged Self → HOD → HR appraisal started by HR for one employee and review cycle.
CREATE TABLE appraisal_cycles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  hod_id uuid,
  hod_name varchar(120) NOT NULL,
  cycle varchar(60) NOT NULL,
  stage varchar(20) NOT NULL,
  created_on date NOT NULL,
  sent_back_note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_appraisal_cycles_stage CHECK (stage IN ('Self Appraisal', 'HOD Appraisal', 'HR Appraisal', 'Completed'))
);
-- EvalParam — Weighted evaluation parameters (Communication, Technical skills…) used by every review / appraisal form.
CREATE TABLE evaluation_parameters (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  weight_pct numeric(5,2) NOT NULL,
  description text,
  applies_to_roles varchar(120) NOT NULL,
  is_active boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_evaluation_parameters_weight_pct_pct CHECK (weight_pct IS NULL OR (weight_pct >= 0 AND weight_pct <= 100))
);
-- GoalDocuments — Child of goals — goal_documents
CREATE TABLE goal_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  goal_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GoalEvaluationParams — Child of goals — goal_evaluation_params (evaluationParams[] → evaluation_parameters.name)
CREATE TABLE goal_evaluation_params (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  goal_id uuid NOT NULL,
  evaluation_parameter_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GoalHistory — Child of goals — goal_history (flattened from history[]: at date, by varchar(120), action text)
CREATE TABLE goal_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  goal_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GoalLinks — Child of goals — goal_links (links[]: label, url https only)
CREATE TABLE goal_links (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  goal_id uuid NOT NULL,
  label varchar(120),
  url varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GoalMetrics — Child of goals — goal_metrics (metrics[]: code, name, unit enum, baseline, target, current, weight)
CREATE TABLE goal_metrics (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  goal_id uuid NOT NULL,
  code varchar(120),
  name varchar(120),
  unit varchar(120),
  baseline varchar(120),
  target varchar(120),
  current varchar(120),
  weight varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GoalMilestones — Child of goals — goal_milestones (milestones[]: code, title, due, done)
CREATE TABLE goal_milestones (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  goal_id uuid NOT NULL,
  code varchar(120),
  title varchar(120),
  due date,
  done boolean,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- Goal — Individual / team / department / organisational goal with metrics, milestones, links, ratings and approval.
CREATE TABLE goals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  title varchar(200) NOT NULL,
  description text,
  level varchar(15) NOT NULL,
  owner_id uuid NOT NULL,
  owner_name varchar(120) NOT NULL,
  created_by_name varchar(120) NOT NULL,
  created_by_role varchar(10) NOT NULL,
  start_date date NOT NULL,
  due_date date NOT NULL,
  weight_pct numeric(5,2) NOT NULL,
  target varchar(300) NOT NULL,
  progress_pct numeric(5,2) NOT NULL,
  status varchar(20) NOT NULL,
  rating_label varchar(20) NOT NULL,
  manager_remarks text,
  self_rating smallint,
  self_justification text,
  manager_rating smallint,
  category varchar(40),
  priority varchar(10),
  quarter varchar(40),
  success_criteria text,
  parent_goal_id uuid,
  user_id uuid,
  assigned_on date,
  reviewer_id uuid,
  reviewer_name varchar(120),
  hr_remarks text,
  owner_notes text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_goals_level CHECK (level IN ('Individual', 'Team', 'Department', 'Organizational')),
  CONSTRAINT ck_goals_created_by_role CHECK (created_by_role IN ('Employee', 'Manager', 'HR', 'Admin')),
  CONSTRAINT ck_goals_weight_pct_pct CHECK (weight_pct IS NULL OR (weight_pct >= 0 AND weight_pct <= 100)),
  CONSTRAINT ck_goals_progress_pct_pct CHECK (progress_pct IS NULL OR (progress_pct >= 0 AND progress_pct <= 100)),
  CONSTRAINT ck_goals_status CHECK (status IN ('Draft', 'Pending Approval', 'Approved', 'Rejected', 'In Progress', 'Completed')),
  CONSTRAINT ck_goals_rating_label CHECK (rating_label IN ('Not Rated', 'Below', 'Meets', 'Exceeds', 'Outstanding')),
  CONSTRAINT ck_goals_priority CHECK (priority IN ('Critical', 'High', 'Medium', 'Low'))
);
-- HrAppraisalAttachments — Child of hr_appraisals — hr_appraisal_attachments
CREATE TABLE hr_appraisal_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  hr_appraisal_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
