-- HrAppraisal — HR-initiated appraisal (trigger, purpose, goals & parameter ratings, linked reviews, pay outcome); approval applies CTC/grade and generates the letter.
CREATE TABLE hr_appraisals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  designation varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  salary_structure_id uuid NOT NULL,
  cycle varchar(60) NOT NULL,
  trigger varchar(40) NOT NULL,
  purpose varchar(40) NOT NULL,
  why_happened text NOT NULL,
  timeline_from date,
  timeline_to date,
  achievements text,
  value_created text,
  justification text,
  overall_score numeric(3,2),
  rating_band varchar(30),
  method varchar(40) NOT NULL,
  current_ctc numeric(14,2) NOT NULL,
  new_ctc numeric(14,2) NOT NULL,
  hike_pct numeric(6,2) NOT NULL,
  new_grade uuid NOT NULL,
  new_designation varchar(120) NOT NULL,
  effective_from date NOT NULL,
  letter_type varchar(30) NOT NULL,
  bonus_amount numeric(14,2) NOT NULL,
  remarks text,
  status varchar(10) NOT NULL,
  created_by varchar(120) NOT NULL,
  created_on date NOT NULL,
  approved_by varchar(120),
  approved_on date,
  letter_ref varchar(30),
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_hr_appraisals_trigger CHECK (trigger IN ('Annual appraisal cycle', 'Manager review outcome', 'HR review outcome', 'Promotion decision', 'Market correction', 'Retention (counter-offer)', 'Confirmation after probation', 'Role change', 'Special recognition / award', 'Client escalation resolved')),
  CONSTRAINT ck_hr_appraisals_purpose CHECK (purpose IN ('Annual increment', 'Promotion / grade change', 'Mid-year increment', 'Role change with revised pay', 'Confirmation after probation', 'Retention correction', 'Performance bonus')),
  CONSTRAINT ck_hr_appraisals_method CHECK (method IN ('Merit Increment', 'Promotion Linked', 'Market Correction', 'Retention Bonus Linked', 'Performance Bonus')),
  CONSTRAINT ck_hr_appraisals_current_ctc_nonneg CHECK (current_ctc IS NULL OR current_ctc >= 0),
  CONSTRAINT ck_hr_appraisals_new_ctc_nonneg CHECK (new_ctc IS NULL OR new_ctc >= 0),
  CONSTRAINT ck_hr_appraisals_hike_pct_pct CHECK (hike_pct IS NULL OR (hike_pct >= 0 AND hike_pct <= 100)),
  CONSTRAINT ck_hr_appraisals_letter_type CHECK (letter_type IN ('Increment Letter', 'Promotion Letter', 'Appointment Letter')),
  CONSTRAINT ck_hr_appraisals_bonus_amount_nonneg CHECK (bonus_amount IS NULL OR bonus_amount >= 0),
  CONSTRAINT ck_hr_appraisals_status CHECK (status IN ('Draft', 'Approved', 'Applied', 'Rejected'))
);
