  designation varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  manager_id uuid,
  manager_name varchar(120) NOT NULL,
  purpose varchar(40) NOT NULL,
  quarter varchar(40) NOT NULL,
  timeline_from date NOT NULL,
  timeline_to date NOT NULL,
  achievements text,
  value_created text,
  justification text NOT NULL,
  asked_for varchar(120),
  expected_grade varchar(10),
  expected_hike_pct numeric(5,2),
  stage varchar(20) NOT NULL,
  submitted_on date,
  outcome_previous_grade varchar(10),
  outcome_new_grade varchar(10),
  outcome_previous_ctc numeric(14,2),
  outcome_new_ctc numeric(14,2),
  outcome_hike_pct numeric(6,2),
  outcome_effective_from date,
  outcome_letter_type varchar(30),
  outcome_letter_ref varchar(30),
  outcome_applied_on date,
  outcome_applied_by varchar(120),
  outcome_remarks text,
  outcome_new_designation varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_self_appraisals_purpose CHECK (purpose IN ('Annual appraisal (increment)', 'Promotion / grade change', 'Mid-year increment', 'Role change with revised pay', 'Confirmation after probation', 'Retention correction')),
  CONSTRAINT ck_self_appraisals_expected_hike_pct_pct CHECK (expected_hike_pct IS NULL OR (expected_hike_pct >= 0 AND expected_hike_pct <= 100)),
  CONSTRAINT ck_self_appraisals_stage CHECK (stage IN ('Draft', 'Manager Review', 'HR Review', 'Unit Head Review', 'Approved', 'Applied', 'Sent back', 'Rejected')),
  CONSTRAINT ck_self_appraisals_outcome_previous_ctc_nonneg CHECK (outcome_previous_ctc IS NULL OR outcome_previous_ctc >= 0),
  CONSTRAINT ck_self_appraisals_outcome_new_ctc_nonneg CHECK (outcome_new_ctc IS NULL OR outcome_new_ctc >= 0),
  CONSTRAINT ck_self_appraisals_outcome_hike_pct_pct CHECK (outcome_hike_pct IS NULL OR (outcome_hike_pct >= 0 AND outcome_hike_pct <= 100))
);
