  CONSTRAINT ck_training_assignments_progress_pct_pct CHECK (progress_pct IS NULL OR (progress_pct >= 0 AND progress_pct <= 100)),
  CONSTRAINT ck_training_assignments_end_date_after_start_date CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
