-- =============================================================================
-- Exit, Grievance & HR Policy
-- =============================================================================

-- ClearanceArea — Clearance master: 7 areas with owner, default officer, hint and checklist.
CREATE TABLE exit_clearance_areas (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exit_clearance_area_code bigint NOT NULL,
  code varchar(12) NOT NULL,
  label varchar(60) NOT NULL,
  owner_function varchar(60) NOT NULL,
  default_officer_name varchar(120),
  hint text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_exit_clearance_areas_code UNIQUE (org_id, exit_clearance_area_code),
  CONSTRAINT ck_exit_clearance_areas_code CHECK (code IN ('finance', 'payroll', 'documents', 'projects', 'assets', 'it', 'admin'))
);
-- ExitClearanceChecklistItems — Child of exit_clearance_areas — exit_clearance_checklist_items (checklist[])
CREATE TABLE exit_clearance_checklist_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exit_clearance_area_id uuid NOT NULL,
  checklist varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ExitClearanceTicks — Child of exit_requests — exit_clearance_ticks (ticked[] checklist items per area)
CREATE TABLE exit_clearance_ticks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exit_request_id uuid NOT NULL,
  ticked varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ExitClearances — Child of exit_requests — exit_clearances (clearances{finance,payroll,documents,projects,assets,it,admin}: area enum, status Pending|Cleared|Blocked, officer_nam
CREATE TABLE exit_clearances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exit_request_id uuid NOT NULL,
  area varchar(20) NOT NULL,
  status varchar(20) NOT NULL,
  officer_name varchar(120),
  cleared_on date,
  amount numeric(14,2),
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_exit_clearances_area CHECK (area IN ('finance', 'payroll', 'documents', 'projects', 'assets', 'it', 'admin')),
  CONSTRAINT ck_exit_clearances_status CHECK (status IN ('Pending', 'Cleared', 'Blocked')),
  CONSTRAINT ck_exit_clearances_amount_nonneg CHECK (amount IS NULL OR amount >= 0)
);
-- ExitRequest — Resignation / termination exit file: manager & HR decisions, notice period, officer-wise clearance checklist, F&F, exit interview, completion.
CREATE TABLE exit_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  email varchar(160) NOT NULL,
  designation varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  branch varchar(80) NOT NULL,
  manager_id uuid NOT NULL,
  manager_name varchar(120) NOT NULL,
  applied_on date NOT NULL,
  reason varchar(60) NOT NULL,
  description text NOT NULL,
  requested_lwd date NOT NULL,
  resignation_letter varchar(200),
  stage varchar(20) NOT NULL,
  manager_decision varchar(10),
  manager_decided_by varchar(120),
  manager_decided_on date,
  manager_note text,
  hr_decision varchar(10),
  hr_decided_by varchar(120),
  hr_decided_on date,
  hr_note text,
  clearance_started_on date,
  clearance_completed_on date,
  notice_days smallint,
  notice_start date,
  last_working_day date,
  exit_interview_done boolean NOT NULL,
  exit_interview_mode varchar(20),
  exit_interview_on date,
  exit_interview_by varchar(120),
  exit_interview_file varchar(200),
  exit_interview_note text,
  fnf_settled boolean NOT NULL,
  fnf_payment_ref varchar(60),
  retained_on date,
  completed_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_exit_requests_email_fmt CHECK (email IS NULL OR email ~ '^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$'),
  CONSTRAINT ck_exit_requests_reason CHECK (reason IN ('Better career opportunity', 'Higher studies', 'Relocation', 'Compensation', 'Work-life balance', 'Health reasons', 'Personal reasons', 'Career change', 'Termination — …')),
  CONSTRAINT ck_exit_requests_stage CHECK (stage IN ('Manager Review', 'Manager Rejected', 'HR Review', 'HR Rejected', 'Notice Period', 'HR Clearance', 'Final Settlement', 'Exit Completed', 'Retained', 'Withdrawn')),
  CONSTRAINT ck_exit_requests_manager_decision CHECK (manager_decision IN ('Approved', 'Rejected')),
  CONSTRAINT ck_exit_requests_hr_decision CHECK (hr_decision IN ('Approved', 'Rejected')),
  CONSTRAINT ck_exit_requests_exit_interview_mode CHECK (exit_interview_mode IN ('Employee portal', 'HR interview', 'Uploaded form'))
);
-- ExitSurvey — Exit survey / interview responses (one per exit).
CREATE TABLE exit_surveys (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  exit_request_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  submitted_on date NOT NULL,
  primary_reason varchar(120) NOT NULL,
  rating_manager smallint NOT NULL,
  rating_culture smallint NOT NULL,
  rating_growth smallint NOT NULL,
  rating_compensation smallint NOT NULL,
  rating_work_life smallint NOT NULL,
  would_rejoin varchar(5) NOT NULL,
  would_recommend varchar(5) NOT NULL,
  feedback text,
  interviewer varchar(120) NOT NULL,
  interview_notes text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_exit_surveys_would_rejoin CHECK (would_rejoin IN ('Yes', 'Maybe', 'No')),
  CONSTRAINT ck_exit_surveys_would_recommend CHECK (would_recommend IN ('Yes', 'Maybe', 'No'))
);
-- ExitTimeline — Child of exit_requests — exit_timeline (timeline[]: stage, by, role, on, note)
CREATE TABLE exit_timeline (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exit_request_id uuid NOT NULL,
  stage varchar(120),
  action_by varchar(120),
  role varchar(120),
  action_on date,
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- FnfConfig — Exit / gratuity / F&F policy per entity.
CREATE TABLE fnf_config (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  gratuity_days_per_year numeric(5,2) NOT NULL,
  gratuity_min_years numeric(4,1) NOT NULL,
  gratuity_round_up_months smallint NOT NULL,
  gratuity_cap numeric(14,2) NOT NULL,
  notice_recovery varchar(10) NOT NULL,
  notice_recovery_basis varchar(5) NOT NULL,
  leave_encashment_basis varchar(5) NOT NULL,
  leave_overdraw_recovery boolean NOT NULL,
  loan_recovery_from_fnf boolean NOT NULL,
  settlement_days_after_lwd smallint NOT NULL,
  rejoin_continuity_days smallint NOT NULL,
  exit_survey_mandatory boolean NOT NULL,
  retention_owner_roles varchar(20)[] NOT NULL,
  updated_by varchar(120) NOT NULL,
  updated_on date NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_fnf_config_notice_recovery CHECK (notice_recovery IN ('Optional', 'Always', 'Never')),
  CONSTRAINT ck_fnf_config_notice_recovery_basis CHECK (notice_recovery_basis IN ('Gross', 'Basic')),
  CONSTRAINT ck_fnf_config_leave_encashment_basis CHECK (leave_encashment_basis IN ('Gross', 'Basic'))
);
-- FnfHistory — Child of fnf_statements — fnf_history (flattened from history[]: at date, by varchar(120), action text)
CREATE TABLE fnf_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fnf_statement_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- FnfLines — Child of fnf_statements — fnf_lines (lines[]: label, amount numeric(14,2), kind earning|deduction, note, optional, enabled)
CREATE TABLE fnf_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fnf_statement_id uuid NOT NULL,
  label varchar(120),
  amount numeric(14,2),
  kind varchar(120),
  note text,
  optional varchar(120),
  enabled varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_fnf_lines_amount_nonneg CHECK (amount IS NULL OR amount >= 0)
);
-- FnfStatement — Full & final settlement statement computed from the exit date.
CREATE TABLE fnf_statements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  exit_request_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  last_working_day date NOT NULL,
  exit_date date NOT NULL,
  notice_days smallint NOT NULL,
  notice_served_days smallint NOT NULL,
  final_period char(7) NOT NULL,
  gross numeric(14,2) NOT NULL,
  deductions numeric(14,2) NOT NULL,
  net_payable numeric(14,2) NOT NULL,
  gratuity jsonb NOT NULL,
  status varchar(20) NOT NULL,
  prepared_by varchar(120) NOT NULL,
  prepared_on date NOT NULL,
  approved_by varchar(120),
  paid_on date,
  payment_ref varchar(60),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_fnf_statements_gross_nonneg CHECK (gross IS NULL OR gross >= 0),
  CONSTRAINT ck_fnf_statements_net_payable_nonneg CHECK (net_payable IS NULL OR net_payable >= 0),
  CONSTRAINT ck_fnf_statements_status CHECK (status IN ('Draft', 'HR reviewed', 'Finance approved', 'Paid'))
);
-- GrievanceAttachments — Child of grievances — grievance_attachments
CREATE TABLE grievance_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grievance_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GrievanceHistory — Child of grievances — grievance_history (flattened from history[]: at date, by varchar(120), action text)
CREATE TABLE grievance_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grievance_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GrievanceInvestigationNotes — Child of grievances — grievance_investigation_notes (investigation[]: at, by, note, visible_to_employee)
CREATE TABLE grievance_investigation_notes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grievance_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  note text,
  visible_to_employee boolean,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- GrievanceRouting — Category → owner, committee and SLA (days) matrix.
CREATE TABLE grievance_routing (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  category varchar(30) NOT NULL,
  owner_name varchar(120) NOT NULL,
  committee varchar(60) NOT NULL,
  ack_days smallint NOT NULL,
  resolve_days smallint NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid
);
-- Grievance — Grievance redressal case: routed by category to committee/owner with ack & resolution SLAs, investigation log, resolution, employee confirmation or appeal.
CREATE TABLE grievances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  display_name varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  branch varchar(80) NOT NULL,
  is_anonymous boolean NOT NULL,
  category varchar(30) NOT NULL,
  severity varchar(10) NOT NULL,
  subject varchar(150) NOT NULL,
  description text NOT NULL,
  against varchar(120),
  raised_on date NOT NULL,
  status varchar(20) NOT NULL,
  owner_name varchar(120) NOT NULL,
  committee varchar(60) NOT NULL,
  ack_due date NOT NULL,
  resolve_due date NOT NULL,
  acknowledged_on date,
  resolved_on date,
  closed_on date,
  resolution text,
  action_taken text,
  employee_rating smallint,
  employee_feedback text,
  appeal_reason text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_grievances_category CHECK (category IN ('Harassment (POSH)', 'Discrimination', 'Workplace safety', 'Payroll / salary dispute', 'Leave / attendance', 'Manager behaviour', 'Facilities', 'Policy violation', 'Other')),
  CONSTRAINT ck_grievances_severity CHECK (severity IN ('Low', 'Medium', 'High', 'Critical')),
  CONSTRAINT ck_grievances_status CHECK (status IN ('Submitted', 'Acknowledged', 'Under investigation', 'Resolved', 'Appealed', 'Closed', 'Withdrawn'))
);
-- HrPolicy — Retirement age, notification lead times and channels per entity.
CREATE TABLE hr_policies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  retirement_age smallint NOT NULL,
  retirement_notice_days smallint NOT NULL,
  probation_reminder_days smallint NOT NULL,
  birthday_notice_days smallint NOT NULL,
  anniversary_notice_days smallint NOT NULL,
  contract_extension_months smallint NOT NULL,
  notify_channels varchar(10)[] NOT NULL,
  updated_on date NOT NULL,
  updated_by varchar(120) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid
);
-- NotificationOutboxEntry — Computed automation outbox (birthdays, anniversaries, retirement, probation-ending to HOD, retirement processed). Derived, not stored today.
CREATE TABLE notification_outbox (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  notification_outbox_code bigint NOT NULL,
  code varchar(40) NOT NULL,
  kind varchar(30) NOT NULL,
  recipient varchar(200) NOT NULL,
  recipient_email varchar(300) NOT NULL,
  subject varchar(200) NOT NULL,
  body text NOT NULL,
  trigger_date date NOT NULL,
  due_on date NOT NULL,
  channel varchar(40) NOT NULL,
  status varchar(10) NOT NULL,
  sent_on date,
  employee_id uuid NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_notification_outbox_code UNIQUE (org_id, notification_outbox_code),
  CONSTRAINT ck_notification_outbox_kind CHECK (kind IN ('Birthday', 'Work anniversary', 'Retirement approaching', 'Probation ending (HOD)', 'Retirement processed')),
  CONSTRAINT ck_notification_outbox_status CHECK (status IN ('Scheduled', 'Sent'))
);
-- RejoinCase — Rejoin after a completed exit — continuity (original DOJ) within the window or fresh hire.
CREATE TABLE rejoin_cases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  exit_request_id uuid NOT NULL,
  exited_on date NOT NULL,
  requested_on date NOT NULL,
  rejoin_on date NOT NULL,
  days_gap smallint NOT NULL,
  mode varchar(40) NOT NULL,
  decided_by varchar(120) NOT NULL,
  note text,
  fnf_reversed boolean NOT NULL,
  original_doj date NOT NULL,
  status varchar(10) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_rejoin_cases_mode CHECK (mode IN ('Continuity (original DOJ retained)', 'Fresh hire (new DOJ)')),
  CONSTRAINT ck_rejoin_cases_status CHECK (status IN ('Proposed', 'Approved', 'Rejoined'))
);
-- RetentionAttachments — Child of retention_cases — retention_attachments
CREATE TABLE retention_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  retention_case_id uuid NOT NULL,
  value text NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RetentionCase — Retention discussion for a live resignation with the audit form filled when retained.
CREATE TABLE retention_cases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  exit_request_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  department varchar(80) NOT NULL,
  manager_name varchar(120) NOT NULL,
  started_by varchar(120) NOT NULL,
  started_on date NOT NULL,
  status varchar(15) NOT NULL,
  owner_name varchar(120) NOT NULL,
  reason_stated text NOT NULL,
  offer text,
  outcome_note text,
  hike_pct numeric(6,2),
  closed_on date,
  audit_justification text,
  audit_qualification text,
  audit_discussion text,
  audit_discussed_on date,
  audit_discussed_by varchar(200),
  new_designation varchar(120),
  new_grade varchar(10),
  previous_ctc numeric(14,2),
  new_ctc numeric(14,2),
  effective_from date,
  retention_bonus numeric(14,2),
  clawback_months smallint,
  appraisal_ref varchar(30),
  conditions text,
  approved_by varchar(120),
  approved_on date,
  review_after_months smallint,
  letter_ref varchar(30),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_retention_cases_status CHECK (status IN ('Open', 'In discussion', 'Offer made', 'Retained', 'Not retained', 'Withdrawn')),
  CONSTRAINT ck_retention_cases_hike_pct_pct CHECK (hike_pct IS NULL OR (hike_pct >= 0 AND hike_pct <= 100)),
  CONSTRAINT ck_retention_cases_previous_ctc_nonneg CHECK (previous_ctc IS NULL OR previous_ctc >= 0),
  CONSTRAINT ck_retention_cases_new_ctc_nonneg CHECK (new_ctc IS NULL OR new_ctc >= 0),
  CONSTRAINT ck_retention_cases_retention_bonus_nonneg CHECK (retention_bonus IS NULL OR retention_bonus >= 0)
);
-- RetentionGrounds — Child of retention_cases — retention_grounds (form.grounds[])
CREATE TABLE retention_grounds (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  retention_case_id uuid NOT NULL,
  form varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RetentionHistory — Child of retention_cases — retention_history (flattened from history[]: at date, by varchar(120), action text)
CREATE TABLE retention_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  retention_case_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RetentionOfferKinds — Child of retention_cases — retention_offer_kinds (offerKind[] enum Compensation|Role change|Project change|Location|Flexibility|Counselling)
CREATE TABLE retention_offer_kinds (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
