  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_retention_offer_kinds_offer CHECK (offer IN ('Compensation', 'Role change', 'Project change', 'Location', 'Flexibility', 'Counselling'))
);
-- RetentionTypes — Child of retention_cases — retention_types (form.retentionType[])
CREATE TABLE retention_types (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  retention_case_id uuid NOT NULL,
  form varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- RetirementRecord — Processed retirement, optionally with a re-engagement contract hire.
CREATE TABLE retirements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  org_id uuid NOT NULL,
  retired_on date NOT NULL,
  processed_on date NOT NULL,
  processed_by varchar(120) NOT NULL,
  reason varchar(25) NOT NULL,
  re_engaged boolean NOT NULL,
  contract_hire_id uuid,
  contract_from date,
  contract_months smallint,
  contract_ctc numeric(14,2),
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
