  CONSTRAINT ck_retirements_contract_ctc_nonneg CHECK (contract_ctc IS NULL OR contract_ctc >= 0)
);

-- =============================================================================
-- Projects, Tasks & Assets
-- =============================================================================

-- AssetHistory — Asset audit trail
CREATE TABLE asset_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_history_code bigint NOT NULL,
  asset_id uuid NOT NULL,
  action_at date NOT NULL,
  by_name varchar(120) NOT NULL,
  action varchar(300) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_asset_history_code UNIQUE (org_id, asset_history_code)
);
-- ChecklistResult — Per-item result of the master checklist at issue / at return
CREATE TABLE asset_issuance_checklist (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_issuance_checklist_code bigint NOT NULL,
  issuance_id uuid NOT NULL,
  phase varchar(6) NOT NULL,
  item varchar(160) NOT NULL,
  is_ok boolean NOT NULL,
  remark text,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_asset_issuance_checklist_code UNIQUE (org_id, asset_issuance_checklist_code),
  CONSTRAINT ck_asset_issuance_checklist_phase CHECK (phase IN ('issue', 'return'))
);
-- AssetIssuance — Custody record — one per issue to an employee, with checklist at issue, acknowledgement and the return check.
CREATE TABLE asset_issuances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_issuance_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  asset_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  issued_on date NOT NULL,
  issued_by_name varchar(120),
  purpose varchar(60),
  expected_return date,
  location varchar(160),
  serial_verified boolean,
  condition_on_issue varchar(20) NOT NULL,
  accessories_issued text[],
  employee_ack boolean,
  ack_on date,
  notes text,
  status varchar(12) NOT NULL,
  return_status varchar(20),
  return_requested_on date,
  return_requested_by varchar(120),
  employee_return_remarks text,
  accessories_returned text[],
  condition_on_return varchar(40),
  return_outcome varchar(24),
  return_remarks text,
  return_checked_by varchar(120),
  return_checked_on date,
  return_approved_by varchar(120),
  return_approved_on date,
  returned_on date,
  recovery_amount numeric(14,2),
  asset_issue_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_asset_issuances_code UNIQUE (org_id, asset_issuance_code),
  CONSTRAINT ck_asset_issuances_status CHECK (status IN ('Active', 'Returned', 'Transferred')),
  CONSTRAINT ck_asset_issuances_return_status CHECK (return_status IN ('Not started', 'Requested', 'Checked', 'Approved', 'Issue raised')),
  CONSTRAINT ck_asset_issuances_return_outcome CHECK (return_outcome IN ('OK', 'Damaged', 'Not working', 'Missing accessories', 'Lost')),
  CONSTRAINT ck_asset_issuances_recovery_amount_nonneg CHECK (recovery_amount IS NULL OR recovery_amount >= 0)
);
-- AssetIssueHistory — Child of asset_issues — asset_issue_history (history[]: at, by, action, note)
CREATE TABLE asset_issue_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_issue_id uuid NOT NULL,
  action_at date,
  action_by varchar(120),
  action text,
  note text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- AssetIssue — Condition issue (damage / breakdown / loss) raised from a return check, by the employee or by the asset manager; assessment → (mishandling: manager remarks → Fi
CREATE TABLE asset_issues (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_issue_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  asset_id uuid NOT NULL,
  issuance_id uuid,
  employee_id uuid NOT NULL,
  raised_by_name varchar(120) NOT NULL,
  raised_by uuid NOT NULL,
  raised_on date NOT NULL,
  source varchar(20) NOT NULL,
  category varchar(40) NOT NULL,
  severity varchar(10) NOT NULL,
  description text NOT NULL,
  noticed_on date,
  evidence text[] NOT NULL,
  status varchar(24) NOT NULL,
  cause varchar(30) NOT NULL,
  cause_details text,
  assessed_by varchar(120),
  assessed_on date,
  estimated_cost numeric(14,2),
  manager_id uuid,
  manager_decision varchar(40),
  manager_remarks text,
  manager_decided_on date,
  finance_decision varchar(24),
  recovery_amount numeric(14,2),
  recovery_mode varchar(20),
  finance_remarks text,
  finance_decided_by varchar(120),
  finance_decided_on date,
  resolution varchar(30),
  repair_vendor varchar(160),
  repair_cost numeric(14,2),
  resolved_by varchar(120),
  resolved_on date,
  resolution_notes text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_asset_issues_code UNIQUE (org_id, asset_issue_code),
  CONSTRAINT ck_asset_issues_source CHECK (source IN ('Return check', 'Employee report', 'Asset manager')),
  CONSTRAINT ck_asset_issues_category CHECK (category IN ('Physical damage', 'Not working / breakdown', 'Performance degraded', 'Missing accessories', 'Lost / stolen', 'Software / licence problem', 'Other')),
  CONSTRAINT ck_asset_issues_severity CHECK (severity IN ('Low', 'Medium', 'High', 'Critical')),
  CONSTRAINT ck_asset_issues_status CHECK (status IN ('Open', 'Under assessment', 'Manager review', 'Finance review', 'Repair / replacement', 'Resolved', 'Closed')),
  CONSTRAINT ck_asset_issues_cause CHECK (cause IN ('Undetermined', 'Employee mishandling', 'Asset fault / breakdown')),
  CONSTRAINT ck_asset_issues_estimated_cost_nonneg CHECK (estimated_cost IS NULL OR estimated_cost >= 0),
  CONSTRAINT ck_asset_issues_manager_decision CHECK (manager_decision IN ('Agree — employee at fault', 'Disagree — treat as asset fault', 'Partial responsibility')),
  CONSTRAINT ck_asset_issues_finance_decision CHECK (finance_decision IN ('Recover full cost', 'Recover partially', 'Waive')),
  CONSTRAINT ck_asset_issues_recovery_amount_nonneg CHECK (recovery_amount IS NULL OR recovery_amount >= 0),
  CONSTRAINT ck_asset_issues_recovery_mode CHECK (recovery_mode IN ('Salary deduction', 'Direct payment', 'Insurance claim', 'Waived')),
  CONSTRAINT ck_asset_issues_resolution CHECK (resolution IN ('Repaired', 'Replaced', 'Written off', 'Returned to stock', 'Retired', 'Recovered from employee')),
  CONSTRAINT ck_asset_issues_repair_cost_nonneg CHECK (repair_cost IS NULL OR repair_cost >= 0)
);
-- AssetRequest — Employee request for an asset, approved HOD → HR business partner → Admin, then fulfilled from stock.
CREATE TABLE asset_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_request_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  employee_name varchar(120) NOT NULL,
  asset_type_id uuid NOT NULL,
  kind varchar(20) NOT NULL,
  reason text NOT NULL,
  urgency varchar(10) NOT NULL,
  raised_on date NOT NULL,
  needed_by date,
  purpose varchar(60),
  specifications text,
  project_id uuid,
  duration varchar(30),
  status varchar(10) NOT NULL,
  issued_asset_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_asset_requests_code UNIQUE (org_id, asset_request_code),
  CONSTRAINT ck_asset_requests_kind CHECK (kind IN ('Hardware', 'Software License', 'Access', 'Vehicle', 'Equipment', 'Furniture')),
  CONSTRAINT ck_asset_requests_urgency CHECK (urgency IN ('Low', 'Normal', 'High', 'Critical')),
  CONSTRAINT ck_asset_requests_status CHECK (status IN ('Pending', 'Approved', 'Rejected', 'Issued'))
);
-- AssetTransfer — Handover of an issued asset between two employees of the same organisation.
CREATE TABLE asset_transfers (
