);
-- AssetTypeMaster — Asset master (Master Data → Assets): type, category, serial rule, depreciation, default checklist & accessories, default return period.
CREATE TABLE asset_types (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_type_code varchar(20) NOT NULL,
