  CONSTRAINT uq_asset_types_code UNIQUE (org_id, asset_type_code),
  CONSTRAINT ck_asset_types_kind CHECK (kind IN ('Hardware', 'Software License', 'Access', 'Vehicle', 'Equipment', 'Furniture')),
  CONSTRAINT ck_asset_types_depreciation_pct_pct CHECK (depreciation_pct IS NULL OR (depreciation_pct >= 0 AND depreciation_pct <= 100))
);
-- Asset — Organisation-owned asset (hardware, licence, vehicle …) — never group-owned.
CREATE TABLE assets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  tag varchar(30) NOT NULL,
  name varchar(160) NOT NULL,
  asset_type_id uuid NOT NULL,
  kind varchar(20) NOT NULL,
