  status varchar(20) NOT NULL,
  license_key varchar(120),
  seats integer,
  renewal_date date,
  holder_id uuid,
  issued_on date,
  location varchar(160),
  custodian_dept varchar(80),
  accessories text[],
  useful_life_years numeric(4,1),
  attachments text[],
  notes text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_assets_code UNIQUE (org_id, asset_code),
  CONSTRAINT ck_assets_kind CHECK (kind IN ('Hardware', 'Software License', 'Access', 'Vehicle', 'Equipment', 'Furniture')),
  CONSTRAINT ck_assets_cost_nonneg CHECK (cost IS NULL OR cost >= 0),
  CONSTRAINT ck_assets_condition CHECK (condition IN ('Excellent', 'Good', 'Fair', 'Poor', 'Damaged', 'Not working', 'Active')),
  CONSTRAINT ck_assets_status CHECK (status IN ('In Stock', 'Issued', 'Return Pending', 'Under Maintenance', 'Retired', 'Lost'))
);
-- ProjectHistory — Audit trail of project edits
CREATE TABLE project_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_history_code bigint NOT NULL,
  project_id uuid NOT NULL,
  action_at date NOT NULL,
  by_name varchar(120) NOT NULL,
  action varchar(200) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_project_history_code UNIQUE (org_id, project_history_code)
);
-- ProjectLinks — Child of projects — project_links (links[])
CREATE TABLE project_links (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL,
  links varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ProjectMember — Project team (manager auto-added as 'Manager')
CREATE TABLE project_members (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  project_role varchar(80) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_project_members_key UNIQUE (project_id, employee_id)
);
-- ProjectMilestone — Milestones
CREATE TABLE project_milestones (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_milestone_code varchar(40) NOT NULL,
  project_id uuid NOT NULL,
  title varchar(200) NOT NULL,
  due_date date NOT NULL,
  is_done boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_project_milestones_code UNIQUE (org_id, project_milestone_code)
);
-- Project — Client / internal project with purpose, people, commercials and milestones. Tasks link via tasks.project_id.
CREATE TABLE projects (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  code varchar(20) NOT NULL,
  name varchar(200) NOT NULL,
  client varchar(160) NOT NULL,
  client_contact varchar(160),
  client_email varchar(160),
  description text,
  project_type varchar(40),
  purpose text,
  objectives text,
  scope text,
  deliverables text,
  risks text,
  department_id uuid,
  branch varchar(120),
  manager_id uuid NOT NULL,
  manager_name varchar(120) NOT NULL,
  sponsor_id uuid,
  sponsor_name varchar(120),
  start_date date NOT NULL,
  end_date date NOT NULL,
  priority varchar(10) NOT NULL,
  status varchar(20) NOT NULL,
  phase varchar(20),
  progress_override_pct smallint NOT NULL,
  billing_type varchar(40),
  budget numeric(14,2),
  currency char(3),
  cost_centre varchar(40),
  po_number varchar(60),
  tags text[],
  attachments text[],
  created_by_name varchar(120),
  created_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_projects_code UNIQUE (org_id, project_code),
  CONSTRAINT ck_projects_project_type CHECK (project_type IN ('Client engagement', 'Internal product', 'Support & maintenance (AMC)', 'Implementation / rollout', 'Consulting / advisory', 'R&D / POC', 'Infrastructure')),
  CONSTRAINT ck_projects_priority CHECK (priority IN ('Low', 'Medium', 'High', 'Critical')),
  CONSTRAINT ck_projects_status CHECK (status IN ('Planning', 'Active', 'On Hold', 'Completed')),
  CONSTRAINT ck_projects_phase CHECK (phase IN ('Initiation', 'Planning', 'Execution', 'UAT', 'Go-live', 'Hypercare', 'Closure')),
  CONSTRAINT ck_projects_billing_type CHECK (billing_type IN ('Fixed price', 'Time & material', 'Retainer', 'Milestone based', 'Non-billable (internal)')),
  CONSTRAINT ck_projects_budget_nonneg CHECK (budget IS NULL OR budget >= 0),
  CONSTRAINT ck_projects_currency CHECK (currency IN ('INR', 'USD', 'EUR', 'GBP', 'AED', 'SAR')),
  CONSTRAINT ck_projects_end_date_after_start_date CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);
-- TaskAssignees — Child of tasks — task_assignees (assignees[] → task_id, employee_id)
CREATE TABLE task_assignees (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id uuid NOT NULL,
  assignees varchar(120),
  employee_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- TaskAttachments — Child of tasks — task_attachments (attachments[])
CREATE TABLE task_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id uuid NOT NULL,
  attachments varchar(120),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- TaskChecklistItem — Sub-task checklist
CREATE TABLE task_checklist_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  task_checklist_item_code varchar(40) NOT NULL,
  task_id uuid NOT NULL,
  title varchar(200) NOT NULL,
  is_done boolean NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_task_checklist_items_code UNIQUE (org_id, task_checklist_item_code)
);
-- TaskLink — External links on a task (http/https only)
CREATE TABLE task_links (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id uuid NOT NULL,
  label varchar(120) NOT NULL,
  url varchar(1000) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_task_links_key UNIQUE (task_id, url)
);
-- TaskUpdate — Activity / progress entries on a task. Entries carrying hours/progress/status are employee progress posts awaiting approval; others are notes.
CREATE TABLE task_updates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id uuid NOT NULL,
  action_at date NOT NULL,
  by_name varchar(120) NOT NULL,
  note text NOT NULL,
  hours_total numeric(7,2),
  progress_pct smallint,
  status varchar(20),
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT ck_task_updates_hours_total_nonneg CHECK (hours_total IS NULL OR hours_total >= 0),
  CONSTRAINT ck_task_updates_status CHECK (status IN ('Not Started', 'In Progress', 'On Hold', 'Completed'))
);
-- Task — One task in the single shared task store — stand-alone (Miscellaneous) or under a project. Read by Tasks, Projects & Assignments, My Team and the employee porta
CREATE TABLE tasks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  task_code varchar(20) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(200) NOT NULL,
  description text,
  details text,
  project_id uuid,
  priority varchar(10) NOT NULL,
  status varchar(20) NOT NULL,
  approval_state varchar(20) NOT NULL,
  purpose varchar(60),
  category varchar(60),
  estimated_hours numeric(7,2) NOT NULL,
  logged_hours numeric(7,2) NOT NULL,
  progress_pct smallint NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  due_date date NOT NULL,
  est_delivery_at timestamptz NOT NULL,
  is_team_task boolean,
  team_name varchar(80),
  concerned_manager_id uuid,
  concerned_manager_name varchar(120),
  concerned_person_id uuid,
  client varchar(160),
  tags text[],
  primary_attachment varchar(255),
  depends_on varchar(20)[],
  is_billable boolean,
  created_by_name varchar(120) NOT NULL,
  employee_id uuid,
  created_on date,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_tasks_code UNIQUE (org_id, task_code),
  CONSTRAINT ck_tasks_priority CHECK (priority IN ('Low', 'Medium', 'High', 'Critical')),
  CONSTRAINT ck_tasks_status CHECK (status IN ('Not Started', 'In Progress', 'On Hold', 'Completed')),
  CONSTRAINT ck_tasks_approval_state CHECK (approval_state IN ('Not Submitted', 'Pending', 'Approved', 'Rejected')),
  CONSTRAINT ck_tasks_purpose CHECK (purpose IN ('Client deliverable', 'Internal improvement', 'Bug fix / incident', 'Compliance / statutory', 'Onboarding / enablement', 'Sales / pre-sales', 'Research / POC', 'Operations')),
  CONSTRAINT ck_tasks_category CHECK (category IN ('Development', 'Testing / QA', 'Design', 'Documentation', 'Client deliverable', 'Support / maintenance', 'Data / reporting', 'Compliance', 'Internal / admin', 'Research')),
  CONSTRAINT ck_tasks_end_date_after_start_date CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date)
);

-- =============================================================================
-- Helpdesk & Reporting
-- =============================================================================

-- ExpenseRow — Executive seed: budget vs actual per cost head per FY month
CREATE TABLE fin_expense_monthly (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  financial_year varchar(10) NOT NULL,
  month_index smallint NOT NULL,
  cost_head varchar(60) NOT NULL,
  cost_centre varchar(40) NOT NULL,
  actual numeric(14,2) NOT NULL,
  budget numeric(14,2) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_fin_expense_monthly_key UNIQUE (org_id, financial_year, month_index, cost_head),
  CONSTRAINT ck_fin_expense_monthly_financial_year_fmt CHECK (financial_year IS NULL OR financial_year ~ '^[0-9]{4}-[0-9]{2}$'),
  CONSTRAINT ck_fin_expense_monthly_cost_head CHECK (cost_head IN ('Salaries & Wages', 'Statutory Contributions', 'Facility & Rent', 'Cloud & Licences', 'Travel & Conveyance', 'Recruitment & Training', 'Marketing', 'Professional Fees')),
  CONSTRAINT ck_fin_expense_monthly_budget_nonneg CHECK (budget IS NULL OR budget >= 0)
);
-- RevenueRow — Executive seed: invoiced vs collected per client per FY month
CREATE TABLE fin_revenue_monthly (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  financial_year varchar(10) NOT NULL,
  month_index smallint NOT NULL,
  client varchar(120) NOT NULL,
  service_line varchar(80) NOT NULL,
  region varchar(40) NOT NULL,
  invoiced numeric(14,2) NOT NULL,
  collected numeric(14,2) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_fin_revenue_monthly_key UNIQUE (org_id, financial_year, month_index, client),
  CONSTRAINT ck_fin_revenue_monthly_financial_year CHECK (financial_year IN ('FY 2024-25', 'FY 2025-26', 'FY 2026-27'))
);
-- HelpdeskConfig — Desk-wide settings (singleton per tenant/group).
CREATE TABLE helpdesk_settings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  ticket_prefix varchar(15) NOT NULL,
  auto_close_days smallint NOT NULL,
  allow_requester_pick_agent boolean NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_helpdesk_settings_key UNIQUE (org_id)
);
-- SlaPolicy — First-response and resolution targets per priority
CREATE TABLE helpdesk_sla_policies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL,
  priority varchar(10) NOT NULL,
  first_response_hours numeric(6,2) NOT NULL,
  resolve_hours numeric(6,2) NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_helpdesk_sla_policies_key UNIQUE (org_id, priority),
  CONSTRAINT ck_helpdesk_sla_policies_priority CHECK (priority IN ('Low', 'Medium', 'High', 'Critical'))
);
-- ServiceDepartmentAgents — Child of service_departments — service_department_agents (agentIds[] → department_id, employee_id; ≥ 1)
CREATE TABLE service_department_agents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  service_department_id uuid NOT NULL,
  agent varchar(120),
  employee_id uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- ServiceDepartment — Service desk (IT, Finance & Payroll, HR, Admin, SAP) with head, agents, mailbox (e-mail-to-ticket) and business hours.
CREATE TABLE service_departments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  service_department_code varchar(10) NOT NULL,
  org_id uuid NOT NULL,
  name varchar(80) NOT NULL,
  description text,
  head_id uuid NOT NULL,
  mailbox varchar(160),
  business_hours varchar(80),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_service_departments_code UNIQUE (org_id, service_department_code)
);
-- TicketAttachment — File metadata on a ticket (≤ 10 MB each)
CREATE TABLE ticket_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_attachment_code varchar(40) NOT NULL,
  ticket_id uuid NOT NULL,
  file_name varchar(255) NOT NULL,
  size_bytes integer NOT NULL,
  mime_type varchar(120),
  added_by_name varchar(120) NOT NULL,
  action_at timestamptz NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_ticket_attachments_code UNIQUE (org_id, ticket_attachment_code)
);
-- TicketCategory — Category inside a service department with default owner and priority; HR-GRIEV is confidential.
CREATE TABLE ticket_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_category_code varchar(30) NOT NULL,
  department_id uuid NOT NULL,
  name varchar(80) NOT NULL,
  description text,
  default_agent_id uuid,
  default_priority varchar(10) NOT NULL,
  is_confidential boolean,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_ticket_categories_code UNIQUE (org_id, ticket_category_code),
  CONSTRAINT ck_ticket_categories_default_priority CHECK (default_priority IN ('Low', 'Medium', 'High', 'Critical'))
);
-- TicketEvent — Conversation & activity timeline (public reply, internal note, status, assignment, attachment, system, escalation).
CREATE TABLE ticket_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_event_code varchar(60) NOT NULL,
  ticket_id uuid NOT NULL,
  action_at timestamptz NOT NULL,
  by_id uuid NOT NULL,
  by_name varchar(120) NOT NULL,
  event_type varchar(12) NOT NULL,
  body text NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_ticket_events_code UNIQUE (org_id, ticket_event_code),
  CONSTRAINT ck_ticket_events_event_type CHECK (event_type IN ('reply', 'internal', 'status', 'assignment', 'attachment', 'system', 'escalation'))
);
-- TicketWatcher — People copied on a ticket
CREATE TABLE ticket_watchers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_id uuid NOT NULL,
  employee_id uuid NOT NULL,
  name varchar(120) NOT NULL,
  org_id uuid NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_ticket_watchers_key UNIQUE (ticket_id, employee_id)
);
-- Ticket — Service-desk ticket routed to a department / category / agent with SLA clock, conversation timeline, watchers and attachments.
CREATE TABLE tickets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_code varchar(30) NOT NULL,
  org_id uuid NOT NULL,
  subject varchar(140) NOT NULL,
  description text NOT NULL,
  department_id uuid NOT NULL,
  category_id uuid NOT NULL,
  priority varchar(10) NOT NULL,
  impact varchar(14) NOT NULL,
  status varchar(24) NOT NULL,
  channel varchar(10) NOT NULL,
  requester_id uuid NOT NULL,
  requester_name varchar(120) NOT NULL,
  requester_dept varchar(80) NOT NULL,
  raised_by_id uuid,
  assignee_id uuid,
  assignee_name varchar(120),
  tags text[] NOT NULL,
  related_kind varchar(20),
  related_ref varchar(60),
  email_from varchar(160),
  email_message_id varchar(200),
  email_received_at timestamptz,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  first_response_due timestamptz NOT NULL,
  resolve_due timestamptz NOT NULL,
  first_response_at timestamptz,
  resolved_at timestamptz,
  closed_at timestamptz,
  resolution text,
  reopen_count smallint NOT NULL,
  csat_rating smallint,
  csat_comment text,
  csat_at timestamptz,
  created_by uuid,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  deleted_at timestamptz,
  deleted_by uuid,
  CONSTRAINT uq_tickets_code UNIQUE (org_id, ticket_code),
  CONSTRAINT ck_tickets_priority CHECK (priority IN ('Low', 'Medium', 'High', 'Critical')),
  CONSTRAINT ck_tickets_impact CHECK (impact IN ('Individual', 'Team', 'Department', 'Organisation')),
  CONSTRAINT ck_tickets_status CHECK (status IN ('New', 'Assigned', 'In Progress', 'Waiting on Requester', 'Resolved', 'Closed', 'Reopened')),
  CONSTRAINT ck_tickets_channel CHECK (channel IN ('Portal', 'Email', 'Phone', 'Walk-in')),
  CONSTRAINT ck_tickets_related_kind CHECK (related_kind IN ('Employee', 'Asset', 'Payroll period', 'Leave request', 'Other'))
);

-- =============================================================================
-- Platform Infrastructure
-- =============================================================================

-- File — Stored file metadata; bytes live in object storage.
CREATE TABLE files (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid,
  bucket varchar(80) NOT NULL,
  object_key varchar(400) NOT NULL,
  file_name varchar(260) NOT NULL,
  content_type varchar(120) NOT NULL,
  size_bytes bigint NOT NULL,
  purpose varchar(40) NOT NULL,
  checksum_sha256 char(64),
  uploaded_by uuid NOT NULL,
  scanned_at timestamptz,
  scan_status varchar(20),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_files_purpose CHECK (purpose IN ('employee-document', 'proof', 'claim-bill', 'ticket-attachment', 'offer', 'policy', 'payslip', 'form16', 'statutory-file', 'other')),
  CONSTRAINT ck_files_scan_status CHECK (scan_status IN ('Pending', 'Clean', 'Infected'))
);
-- AuditEvent — Append-only audit trail written by the API for every command.
CREATE TABLE audit_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid,
  actor_user_id uuid,
  actor_role varchar(30),
  action varchar(80) NOT NULL,
  entity_table varchar(80) NOT NULL,
  entity_id uuid,
  entity_code varchar(60),
  before_data jsonb,
  after_data jsonb,
  ip_address inet,
  user_agent varchar(300),
  trace_id varchar(60),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- EventOutbox — Domain events published by commands; drained by the notification and integration workers.
CREATE TABLE event_outbox (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid,
  event_type varchar(80) NOT NULL,
  payload jsonb NOT NULL,
  status varchar(20) NOT NULL,
  attempts integer NOT NULL,
  available_at timestamptz NOT NULL,
  delivered_at timestamptz,
  last_error text,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_event_outbox_status CHECK (status IN ('Pending', 'Processing', 'Delivered', 'Failed'))
);
-- IdempotencyKey — Stored responses for repeated POST commands carrying an Idempotency-Key.
CREATE TABLE idempotency_keys (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid,
  idempotency_key varchar(80) NOT NULL,
  endpoint varchar(160) NOT NULL,
  request_hash char(64) NOT NULL,
  response_status integer,
  response_body jsonb,
  expires_at timestamptz NOT NULL,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL
);
-- JobRun — Execution log of background jobs (payroll computation, statutory files, exports, SLA timers).
CREATE TABLE job_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid,
  job_name varchar(80) NOT NULL,
  status varchar(20) NOT NULL,
  started_at timestamptz,
  finished_at timestamptz,
  input jsonb,
  result jsonb,
  error text,
  triggered_by uuid,
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_job_runs_status CHECK (status IN ('Queued', 'Running', 'Succeeded', 'Failed', 'Cancelled'))
);
-- CodeSequence — Generator for human-readable business codes (SRN-0006, PR-2026-07, LV-000123) per organisation and entity type.
CREATE TABLE code_sequences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid,
  entity_table varchar(80) NOT NULL,
  prefix varchar(20) NOT NULL,
  pad_width integer NOT NULL,
  next_value bigint NOT NULL,
  period_scope varchar(20),
  created_at timestamptz DEFAULT now() NOT NULL,
  created_by uuid,
  updated_at timestamptz DEFAULT now() NOT NULL,
  updated_by uuid,
  row_version integer DEFAULT 1 NOT NULL,
  CONSTRAINT ck_code_sequences_period_scope CHECK (period_scope IN ('None', 'Financial year', 'Calendar year', 'Month'))
);

