-- =============================================================================
-- Shared functions and triggers
-- =============================================================================
CREATE OR REPLACE FUNCTION set_row_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := COALESCE(NEW.created_at, now());
    NEW.updated_at := now();
    NEW.row_version := 1;
  ELSE
    NEW.created_at := OLD.created_at;
    NEW.updated_at := now();
    NEW.row_version := OLD.row_version + 1;
  END IF;
  RETURN NEW;
END $$;

-- current tenant, set by the API once per transaction:  SET LOCAL app.org_id = '<uuid>';
CREATE OR REPLACE FUNCTION current_org_id() RETURNS uuid LANGUAGE plpgsql STABLE AS $$
BEGIN
  RETURN NULLIF(current_setting('app.org_id', true), '')::uuid;
EXCEPTION WHEN others THEN RETURN NULL;
END $$;

-- next business code for a table, e.g. next_code('employees', org, 'SRN')  ->  SRN-0006
CREATE OR REPLACE FUNCTION next_code(p_table varchar, p_org uuid, p_prefix varchar DEFAULT NULL)
RETURNS varchar LANGUAGE plpgsql AS $$
DECLARE v_row code_sequences%ROWTYPE; v_num bigint;
BEGIN
  SELECT * INTO v_row FROM code_sequences
   WHERE entity_table = p_table AND (org_id = p_org OR (org_id IS NULL AND p_org IS NULL))
   FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO code_sequences (org_id, entity_table, prefix, pad_width, next_value)
    VALUES (p_org, p_table, COALESCE(p_prefix, upper(left(p_table, 3))), 4, 1)
    RETURNING * INTO v_row;
  END IF;
  v_num := v_row.next_value;
  UPDATE code_sequences SET next_value = v_num + 1, updated_at = now() WHERE id = v_row.id;
  RETURN v_row.prefix || '-' || lpad(v_num::text, v_row.pad_width, '0');
END $$;


