-- =============================================================================
-- Application role and grants
-- The API connects as seerhr_app (never as the owner/superuser) so that
-- row-level security is enforced. Each request runs:
--   SET LOCAL app.org_id = '<organisation uuid>';
-- =============================================================================
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'seerhr_app') THEN
    CREATE ROLE seerhr_app NOLOGIN;
  END IF;
END $$;
GRANT USAGE ON SCHEMA public TO seerhr_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO seerhr_app;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO seerhr_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO seerhr_app;
-- audit_events is append-only for the application
REVOKE UPDATE, DELETE ON audit_events FROM seerhr_app;


-- =============================================================================
-- Comments
-- =============================================================================

COMMENT ON TABLE biometric_devices IS 'Registered attendance devices per organisation.';
COMMENT ON COLUMN biometric_devices.id IS 'Surrogate primary key.';
COMMENT ON COLUMN biometric_devices.biometric_device_code IS 'DEV-<timestamp>';
COMMENT ON COLUMN biometric_devices.org_id IS 'Map key';
COMMENT ON COLUMN biometric_devices.branch IS 'Should reference organization_branches.id';
COMMENT ON COLUMN biometric_devices.created_at IS 'Row creation timestamp.';
